package com.elialombardi.piccistodo

import androidx.compose.material3.MaterialTheme
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.test.*
import androidx.compose.ui.test.junit4.v2.createComposeRule
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.repository.NotesDataSource
import com.elialombardi.piccistodo.ui.screens.NotesContent
import com.elialombardi.piccistodo.ui.viewmodels.NotesController
import com.google.gson.JsonObject
import kotlinx.coroutines.*
import org.junit.After
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith
import java.time.OffsetDateTime

@RunWith(AndroidJUnit4::class)
class NotesReorderingScreenTest {
    @get:Rule val ui = createComposeRule()
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)
    private val source = Source()
    private val controller = NotesController(source, scope)
    private class Source : NotesDataSource {
        private val date = OffsetDateTime.parse("2026-11-10T00:40:00Z")
        private fun note(id: Long, folder: Long, position: Int) = NotesItem(id, folder, position, "Note $id", "Diary text", "Task description",
            "2026-12-01", true, NotesStyle(bold = true), date, date)
        var rows = listOf(
            NotesFolder(12, "Diary", NotesType.DIARY, 0, null, emptyList(), listOf(note(41, 12, 0), note(42, 12, 1))),
            NotesFolder(15, "Shopping", NotesType.BUY, 1, null, emptyList(), listOf(note(45, 15, 0), note(46, 15, 1))),
            NotesFolder(16, "Work list", NotesType.TASKS, 2, null, listOf(
                NotesFolder(17, "First child", NotesType.DIARY, 0, 16, emptyList(), emptyList()),
                NotesFolder(18, "Second child", NotesType.DIARY, 1, 16, emptyList(), emptyList())), listOf(note(47, 16, 0), note(48, 16, 1))))
        val writes = mutableListOf<JsonObject>()
        override suspend fun tree(): List<NotesFolder> {
            fun sorted(rows: List<NotesFolder>): List<NotesFolder> = rows.sortedBy { it.position }.map {
                it.copy(children = sorted(it.children), notes = it.notes.sortedBy { note -> note.position })
            }
            return sorted(rows)
        }
        private fun update(folder: Boolean, id: Long, body: JsonObject) {
            writes += body.deepCopy()
            fun walk(rows: List<NotesFolder>): List<NotesFolder> = rows.map {
                val changed = if (folder && it.id == id) it.copy(position = body["position"].asInt) else it
                changed.copy(children = walk(changed.children), notes = changed.notes.map { n ->
                    if (!folder && n.id == id) n.copy(position = body["position"].asInt) else n
                })
            }
            rows = walk(rows)
        }
        override suspend fun saveFolder(id: Long?, body: JsonObject): Long { update(true, requireNotNull(id), body); return id }
        override suspend fun saveItem(id: Long?, body: JsonObject): NotesItem {
            update(false, requireNotNull(id), body); return rows.folderRows().flatMap { it.folder.notes }.first { it.id == id }
        }
        override suspend fun deleteFolder(id: Long) = error("Not used")
        override suspend fun deleteItem(id: Long) = error("Not used")
    }
    @After fun close() { scope.cancel() }
    private fun text(id: Int) = InstrumentationRegistry.getInstrumentation().targetContext.getString(id)
    private fun show(role: String = "Writer") {
        ui.setContent { MaterialTheme { NotesContent(controller) } }
        ui.runOnIdle { controller.sessionChanged(role, true) }; ready()
    }
    private fun ready() = ui.waitUntil(5000) { controller.state.value.fresh && !controller.state.value.refreshing && !controller.state.value.saving }
    private fun select(id: Long) { ui.runOnIdle { controller.selectFolder(id) }; ui.waitForIdle() }
    private fun menuMove(tag: String, action: Int) {
        val pane = if (tag.startsWith("notes_reorder_folder_")) "notes_folder_navigator" else "notes_item_list"
        ui.onNodeWithTag(pane).performScrollToNode(hasTestTag(tag.replace("notes_reorder_", "notes_")))
        ui.onNodeWithTag(tag).performClick()
        ui.onNodeWithText(text(action)).performClick(); ready()
    }
    private fun drag(from: String, to: String) {
        val fromNode = ui.onNodeWithTag(from)
        val delta = ui.onNodeWithTag(to).fetchSemanticsNode().boundsInRoot.center.y - fromNode.fetchSemanticsNode().boundsInRoot.center.y
        fromNode.performTouchInput { swipe(center, center + Offset(0f, delta), 800) }
        ready()
    }

    @Test fun draggingDiaryNotesPersistsPositionsAndDoesNotOpenTheEditor() {
        show(); select(12)
        ui.onNodeWithTag("notes_item_42").performScrollTo()
        drag("notes_reorder_item_41", "notes_reorder_item_42")
        ui.waitUntil(5000) { controller.state.value.selectedFolder!!.notes.first().id == 42L }
        assertNull(controller.state.value.itemDraft)
        assertEquals(2, source.writes.size)
        assertTrue(source.writes.all { it.keySet() == setOf("position") })
        assertEquals("Diary text", controller.state.value.selectedFolder!!.notes.first().content)
    }

    @Test fun draggingRootFolderKeepsChildrenAndNotesAttached() {
        show()
        ui.onNodeWithTag("notes_folder_16").performScrollTo()
        drag("notes_reorder_folder_16", "notes_reorder_folder_15")
        ui.waitUntil(5000) { controller.state.value.tree[1].id == 16L }
        assertNull(controller.state.value.selectedFolderId)
        assertEquals(listOf(17L, 18L), controller.state.value.tree[1].children.map { it.id })
        assertEquals(listOf(41L, 42L), controller.state.value.tree.first().notes.map { it.id })
        assertTrue(source.writes.all { it.keySet() == setOf("position") })
    }

    @Test fun moveMenuOrdersNestedSiblingsAndAllListTypesWithoutCrossFolderMoves() {
        show()
        menuMove("notes_reorder_folder_18", R.string.notes_move_up)
        assertEquals(listOf(18L, 17L), controller.state.value.tree.last().children.map { it.id })
        assertEquals(listOf(12L, 15L, 16L), controller.state.value.tree.map { it.id })
        listOf(12L to 42L, 15L to 46L, 16L to 48L).forEach { (folder, note) ->
            select(folder); menuMove("notes_reorder_item_$note", R.string.notes_move_up)
            assertEquals(note, controller.state.value.selectedFolder!!.notes.first().id)
        }
        assertTrue(source.writes.all { it.keySet() == setOf("position") })
    }

    @Test fun readerHasNoReorderHandlesAndWriterCannotReorderWithAnEditorOpen() {
        show("Reader")
        ui.onNodeWithTag("notes_reorder_folder_12").assertDoesNotExist()
        select(12); ui.onNodeWithTag("notes_reorder_item_41").assertDoesNotExist()
        ui.runOnIdle { controller.sessionChanged("Admin", true) }; ready(); select(12)
        ui.onNodeWithTag("notes_reorder_item_41").assertIsEnabled()
        ui.runOnIdle { controller.openItem(controller.state.value.selectedFolder!!.notes.first()) }
        // On wide screens the list remains visible beside the editor, but its handles are disabled.
        val handles = ui.onAllNodesWithTag("notes_reorder_item_41").fetchSemanticsNodes()
        if (handles.isNotEmpty()) ui.onNodeWithTag("notes_reorder_item_41").assertIsNotEnabled()
        assertTrue(source.writes.isEmpty())
    }
}

package com.elialombardi.piccistodo

import android.graphics.Bitmap
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.test.*
import androidx.compose.ui.test.junit4.v2.createComposeRule
import androidx.compose.ui.unit.Density
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.repository.NotesDataSource
import com.elialombardi.piccistodo.ui.screens.NotesContent
import com.elialombardi.piccistodo.ui.viewmodels.NotesController
import com.google.gson.JsonObject
import kotlinx.coroutines.*
import org.junit.After
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File
import java.time.OffsetDateTime

@RunWith(AndroidJUnit4::class)
class NotesScreenTest {
    @get:Rule val ui = createComposeRule()
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)
    private val source = Source()
    private val controller = NotesController(source, scope)
    private class Source : NotesDataSource {
        private val date = OffsetDateTime.parse("2026-11-10T00:40:00.123456+02:00")
        private fun note(id: Long, folder: Long, title: String) = NotesItem(id, folder, 0, title, "Styled diary body", "Separate task description",
            "2026-11-14", true, NotesStyle(bold = true), date, date)
        var folders = listOf(
            NotesFolder(12, "Diary root", NotesType.DIARY, 0, null,
                listOf(NotesFolder(13, "Nested tasks", NotesType.TASKS, 0, 12, emptyList(), listOf(note(43, 13, "Task item")))), listOf(note(42, 12, "Diary item"))),
            NotesFolder(15, "Shopping", NotesType.BUY, 0, null, emptyList(), listOf(note(44, 15, "Buy item"))))
        var calls = 0
        var last: JsonObject? = null
        override suspend fun tree() = folders
        override suspend fun saveItem(id: Long?, body: JsonObject): NotesItem {
            calls++; last = body.deepCopy()
            val old = folders.folderRows().flatMap { it.folder.notes }.first { it.id == id }
            val saved = old.copy(title = body["title"]?.asString ?: old.title,
                completed = body["completed"]?.asBoolean ?: old.completed,
                endDate = if (body.has("endDate")) body["endDate"].asString.takeIf { it.isNotEmpty() } else old.endDate)
            fun walk(rows: List<NotesFolder>): List<NotesFolder> = rows.map { it.copy(children = walk(it.children), notes = it.notes.map { n -> if (n.id == id) saved else n }) }
            folders = walk(folders)
            return saved
        }
        override suspend fun saveFolder(id: Long?, body: JsonObject): Long = error("Not used by this UI test")
        override suspend fun deleteFolder(id: Long) = error("Not used by this UI test")
        override suspend fun deleteItem(id: Long) = error("Not used by this UI test")
    }
    @After fun close() { scope.cancel() }
    private fun text(id: Int) = InstrumentationRegistry.getInstrumentation().targetContext.getString(id)
    private fun show(role: String, largeDark: Boolean = false) {
        ui.setContent {
            val density = LocalDensity.current
            CompositionLocalProvider(LocalDensity provides Density(density.density, if (largeDark) 1.8f else density.fontScale)) {
                MaterialTheme(colorScheme = if (largeDark) darkColorScheme() else lightColorScheme()) { NotesContent(controller) }
            }
        }
        ui.runOnIdle { controller.sessionChanged(role, true) }
        ready()
    }
    private fun ready() = ui.waitUntil(5000) { controller.state.value.fresh && !controller.state.value.refreshing && !controller.state.value.saving }
    private fun click(id: Int) = ui.onAllNodesWithText(text(id)).onLast().performScrollTo().performClick()
    private fun screenshot(name: String) {
        ui.waitForIdle()
        val instrumentation = InstrumentationRegistry.getInstrumentation()
        val folder = File(instrumentation.targetContext.getExternalFilesDir(null), "notes-qa").apply { mkdirs() }
        val bitmap = instrumentation.uiAutomation.takeScreenshot()
        File(folder, "$name.png").outputStream().use { bitmap.compress(Bitmap.CompressFormat.PNG, 100, it) }
        bitmap.recycle()
    }
    @Test fun folderNavigatorHasNoItemsAndNestedReaderSelectionIsDirectOnly() {
        show("Reader")
        ui.onNodeWithTag("notes_folder_13").assertExists()
        ui.onNodeWithText("Diary item").assertDoesNotExist()
        ui.onNodeWithText("Task item").assertDoesNotExist()
        screenshot("01-folders-only")
        ui.onNodeWithTag("notes_folder_13").performScrollTo().performClick()
        ui.onNodeWithTag("notes_item_43").assertExists()
        ui.onNodeWithTag("notes_item_42").assertDoesNotExist()
        ui.onAllNodes(isToggleable()).onFirst().assertIsNotEnabled()
        ui.onNodeWithTag("notes_item_43").performScrollTo().performClick()
        ui.onNodeWithText(text(R.string.notes_description)).assertExists()
        ui.onNodeWithText(text(R.string.notes_content)).assertDoesNotExist()
        ui.onAllNodesWithText(text(R.string.notes_save)).assertCountEquals(0)
        ui.onAllNodesWithText(text(R.string.notes_delete)).assertCountEquals(0)
    }
    @Test fun buyToggleIsCompletionOnlyAndEditorDiscardRequiresDecision() {
        show("Writer")
        ui.onNodeWithTag("notes_folder_15").performScrollTo().performClick()
        ui.onNode(isToggleable()).performScrollTo().performClick(); ready()
        assertEquals("{\"completed\":false}", source.last.toString())
        ui.onNodeWithTag("notes_item_44").performScrollTo().performClick()
        ui.onNodeWithText(text(R.string.notes_description)).assertDoesNotExist()
        ui.onNodeWithText(text(R.string.notes_content)).assertDoesNotExist()
        ui.onNodeWithText(text(R.string.notes_end_date)).assertDoesNotExist()
        ui.onNodeWithText(text(R.string.notes_item_title)).performTextReplacement("Unsaved milk")
        click(R.string.notes_close)
        ui.onNodeWithText(text(R.string.notes_discard_title)).assertIsDisplayed()
        ui.onNodeWithText(text(R.string.notes_cancel)).performClick()
        assertEquals("Unsaved milk", controller.state.value.itemDraft!!.title)
        click(R.string.notes_close); ui.onNodeWithText(text(R.string.notes_discard)).performClick()
        assertNull(controller.state.value.itemDraft); assertEquals(1, source.calls)
        screenshot("02-buy-list")
    }
    @Test fun taskDateClearsWithEmptyStringWithoutDiaryControls() {
        show("Writer")
        ui.onNodeWithTag("notes_folder_13").performScrollTo().performClick()
        ui.onNodeWithTag("notes_item_43").performScrollTo().performClick()
        ui.onNodeWithText("2026-11-14").assertExists()
        ui.onNodeWithText(text(R.string.notes_content)).assertDoesNotExist()
        click(R.string.notes_clear_date)
        click(R.string.notes_save); ready()
        assertEquals("{\"endDate\":\"\"}", source.last.toString())
        assertEquals("Separate task description", controller.state.value.itemDraft!!.description)
        screenshot("03-task-editor")
    }
    @Test fun diaryShowsWholeNotePreviewWithoutCompletionOrEndDate() {
        show("Writer", largeDark = true)
        ui.onNodeWithTag("notes_folder_12").performScrollTo().performClick()
        ui.onNodeWithTag("notes_item_42").performScrollTo().performClick()
        ui.onNodeWithText(text(R.string.notes_content)).assertExists()
        ui.onNodeWithText(text(R.string.notes_description)).assertDoesNotExist()
        ui.onNodeWithText(text(R.string.notes_end_date)).assertDoesNotExist()
        ui.onNodeWithText(text(R.string.notes_bold)).performScrollTo().assertExists()
        ui.onNodeWithText(text(R.string.notes_preview)).performScrollTo().assertIsDisplayed()
        screenshot("04-diary-preview-large-dark")
    }
    @Test fun wideLayoutCanHideRestoreFoldersAndSwitchFolderClosesEditor() {
        show("Writer")
        // This assertion also makes the tablet-only run explicit instead of silently passing on phones.
        val wide = ui.onAllNodesWithText(text(R.string.notes_hide_folders)).fetchSemanticsNodes().isNotEmpty()
        if (!wide) return
        ui.onNodeWithTag("notes_folder_12").performScrollTo().performClick()
        ui.onNodeWithTag("notes_item_42").performScrollTo().performClick()
        ui.onNodeWithTag("notes_editor").assertExists()
        ui.onNodeWithTag("notes_item_list").assertExists()
        ui.onNodeWithTag("notes_folder_13").performScrollTo().performClick()
        ui.onNodeWithTag("notes_editor").assertDoesNotExist()
        click(R.string.notes_hide_folders)
        ui.onNodeWithTag("notes_folder_navigator").assertDoesNotExist()
        ui.onNodeWithText(text(R.string.notes_show_folders)).performClick()
        ui.onNodeWithTag("notes_folder_navigator").assertExists()
        screenshot("05-tablet-folders-items")
    }
}

package com.elialombardi.piccistodo

import android.graphics.Bitmap
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.test.*
import androidx.compose.ui.test.junit4.v2.createComposeRule
import androidx.compose.ui.unit.Density
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.repository.TaskDataSource
import com.elialombardi.piccistodo.ui.screens.TasksContent
import com.elialombardi.piccistodo.ui.viewmodels.TasksController
import kotlinx.coroutines.*
import org.junit.After
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File
import java.io.IOException
import java.math.BigDecimal

@RunWith(AndroidJUnit4::class)
class TasksScreenTest {
    @get:Rule val ui = createComposeRule()
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)
    private val source = Source()
    private val controller = TasksController(source, scope)
    private class Source : TaskDataSource {
        val project = Project("11111111-1111-4111-8111-111111111111", "Demo client")
        var projectRows = listOf(project)
        var rows = listOf(
            Task("22222222-2222-4222-8222-222222222222", project.id, project.name,
                "Pending website update", BigDecimal("12.50"), "2026-11-09", description = "Replace the hero image.\nKeep the rest of the page unchanged."),
            Task("33333333-3333-4333-8333-333333333333", project.id, project.name,
                "Sent maintenance", BigDecimal("20.00"), "2026-11-08", "2026-11-10"))
        var failLoad = false
        var failWrite = false
        var writes = 0
        var last: TaskRequest? = null
        override suspend fun tasks(): List<Task> { if (failLoad) throw IOException(); return rows }
        override suspend fun projects() = projectRows
        override suspend fun task(id: String) = rows.first { it.id == id }
        override suspend fun saveTask(id: String?, request: TaskRequest): Task {
            writes++; last = request; if (failWrite) throw IOException()
            val saved = Task(id ?: "44444444-4444-4444-8444-444444444444", request.projectId,
                projectRows.first { it.id == request.projectId }.name, request.name, request.cost, request.date,
                request.sentOn.takeIf { it.isNotEmpty() }, request.description.takeIf { it.isNotEmpty() })
            rows = rows.filterNot { it.id == saved.id } + saved; return saved
        }
        override suspend fun createProject(request: ProjectRequest): Project {
            val saved = Project("55555555-5555-4555-8555-555555555555", request.name, request.description)
            projectRows = projectRows + saved; return saved
        }
    }
    @After fun close() { scope.cancel() }
    private fun text(id: Int) = InstrumentationRegistry.getInstrumentation().targetContext.getString(id)
    private fun show(largeDark: Boolean = false) {
        ui.setContent {
            val density = LocalDensity.current
            CompositionLocalProvider(LocalDensity provides Density(density.density, if (largeDark) 1.8f else density.fontScale)) {
                MaterialTheme(colorScheme = if (largeDark) darkColorScheme() else lightColorScheme()) {
                    TasksContent(controller, {}, {})
                }
            }
        }
        ready()
    }
    private fun ready() = ui.waitUntil(5000) {
        controller.state.value.tasksLoaded && controller.state.value.projectsLoaded &&
            !controller.state.value.refreshing && !controller.state.value.saving
    }
    private fun click(id: Int) {
        val node = ui.onAllNodesWithText(text(id)).onLast()
        if (!node.isDisplayed()) node.performScrollTo()
        node.performClick()
    }
    private fun overviewClick(value: String) {
        ui.onNode(hasScrollAction()).performScrollToNode(hasText(value))
        ui.onNodeWithText(value).performClick()
    }
    private fun screenshot(name: String) {
        ui.waitForIdle()
        val instrumentation = InstrumentationRegistry.getInstrumentation()
        val folder = File(instrumentation.targetContext.getExternalFilesDir(null), "tasks-qa").apply { mkdirs() }
        val bitmap = instrumentation.uiAutomation.takeScreenshot()
        File(folder, "$name.png").outputStream().use { bitmap.compress(Bitmap.CompressFormat.PNG, 100, it) }
        bitmap.recycle()
    }

    @Test fun overviewDefaultsToPendingAndHistoryIncludesBothStatuses() {
        show(); screenshot("01-overview")
        ui.onNode(isSelectable() and hasAnyDescendant(hasText(text(R.string.tasks_not_sent))), useUnmergedTree = true).assertIsSelected()
        overviewClick(text(R.string.tasks_history))
        ui.onNode(hasScrollAction()).performScrollToNode(hasText("Sent maintenance"))
        ui.onNodeWithText("Sent maintenance").assertExists()
        ui.onNode(hasScrollAction()).performScrollToNode(hasText("Pending website update"))
        ui.onNodeWithText("Pending website update").assertExists()
        assertEquals(1, controller.state.value.tasks.summary().pendingCount)
    }

    @Test fun statusConfirmationOnlyChangesDateAndCanBeCleared() {
        show(); overviewClick("Pending website update")
        click(R.string.tasks_mark_sent)
        ui.onAllNodesWithText(text(R.string.tasks_status_explanation)).onLast().assertExists()
        screenshot("02-status-confirmation")
        click(R.string.tasks_confirm); ready()
        assertTrue(controller.state.value.selected!!.isSent)
        assertEquals("Pending website update", source.last!!.name)
        assertEquals(BigDecimal("12.50"), source.last!!.cost)
        click(R.string.tasks_mark_not_sent)
        ui.onNodeWithText(text(R.string.tasks_clear_confirm)).assertExists()
        click(R.string.tasks_confirm); ready()
        assertEquals("", source.last!!.sentOn); assertFalse(controller.state.value.selected!!.isSent)
        assertEquals(2, source.writes)
    }

    @Test fun projectCreationPreservesFormAndDecimalCommaSavesAsNumber() {
        show(); overviewClick(text(R.string.tasks_add))
        ui.onNodeWithText(text(R.string.tasks_name)).performClick().performTextReplacement("New maintenance")
        ui.onNodeWithText(text(R.string.tasks_cost)).performTextReplacement("-10,25")
        click(R.string.tasks_add_project)
        ui.onNodeWithText(text(R.string.tasks_project_name)).performTextReplacement("New client")
        click(R.string.tasks_save); ready()
        assertEquals("New maintenance", controller.state.value.draft!!.name)
        assertEquals("55555555-5555-4555-8555-555555555555", controller.state.value.draft!!.projectId)
        ui.onNodeWithText(text(R.string.tasks_date)).performScrollTo().performTextReplacement("2026-11-10")
        screenshot("03-task-editor")
        click(R.string.tasks_save); ready()
        assertNull(controller.state.value.draft); assertEquals(BigDecimal("-10.25"), source.last!!.cost)
        assertEquals("2026-11-10", source.last!!.date)
    }

    @Test fun noProjectsBlocksSaveAndDirtyBackRequiresConfirmation() {
        source.projectRows = emptyList(); source.rows = emptyList(); show()
        overviewClick(text(R.string.tasks_add))
        ui.onNodeWithText(text(R.string.tasks_no_projects)).assertExists()
        ui.onNodeWithText(text(R.string.tasks_save)).performScrollTo().assertIsNotEnabled()
        ui.onNodeWithText(text(R.string.tasks_name)).performScrollTo().performTextReplacement("Unsaved work")
        ui.onNodeWithContentDescription(text(R.string.tasks_back)).performClick()
        ui.onNodeWithText(text(R.string.tasks_discard_title)).assertIsDisplayed()
        click(R.string.tasks_keep_editing)
        assertEquals("Unsaved work", controller.state.value.draft!!.name)
        ui.onNodeWithContentDescription(text(R.string.tasks_back)).performClick(); click(R.string.tasks_discard)
        assertNull(controller.state.value.draft); assertEquals(0, source.writes)
    }

    @Test fun refreshFailureIsStaleNotEmptyAndUncertainSaveRetainsInput() {
        show(); ui.runOnIdle { source.failLoad = true; controller.refresh() }; ready()
        ui.onAllNodesWithText(text(R.string.tasks_stale)).onFirst().assertExists()
        ui.onNodeWithText(text(R.string.tasks_tasks_failed)).assertExists()
        screenshot("04-stale-error")
        assertEquals(2, controller.state.value.tasks.size)
        ui.runOnIdle { source.failLoad = false; controller.refresh() }; ready()
        overviewClick("Pending website update"); click(R.string.tasks_edit)
        ui.onNodeWithText(text(R.string.tasks_name)).performTextReplacement("Retain this edit")
        source.failWrite = true; click(R.string.tasks_save); ready()
        ui.onNodeWithText(text(R.string.tasks_save)).performScrollTo().assertIsNotEnabled()
        assertEquals("Retain this edit", controller.state.value.draft!!.name)
        assertTrue(controller.state.value.uncertain); assertEquals(1, source.writes)
    }

    @Test fun largeTextDarkHistoryAndDetailsRemainScrollable() {
        show(largeDark = true); overviewClick(text(R.string.tasks_history))
        overviewClick("Pending website update")
        ui.onNodeWithText(text(R.string.tasks_mark_sent)).performScrollTo().assertIsDisplayed()
        screenshot("05-large-text-dark-details")
        assertEquals("Replace the hero image.\nKeep the rest of the page unchanged.", controller.state.value.selected!!.description)
    }
}

package com.elialombardi.piccistodo

import androidx.compose.foundation.layout.*
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.outlined.FolderOpen
import androidx.compose.material.icons.outlined.WorkOutline
import androidx.compose.material.icons.outlined.PersonOutline
import androidx.compose.material.icons.outlined.LocalGasStation
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.ui.Modifier
import androidx.compose.ui.res.stringResource
import androidx.navigation.NavType
