@Composable
fun NotesScreen(onAuthenticationRequired: () -> Unit, onRootChanged: (Boolean) -> Unit = {},
                initialFolderId: Long? = null, initialCreate: Boolean = false, initialFolderForm: Boolean = false,
                viewModel: NotesViewModel = hiltViewModel()) {
    NotesContent(viewModel.controller, onAuthenticationRequired, onRootChanged, initialFolderId, initialCreate, initialFolderForm)
}
@Composable
private fun typeLabel(type: NotesType) = stringResource(when (type) {
    NotesType.BUY -> R.string.notes_buy
    NotesType.TASKS -> R.string.notes_tasks
    NotesType.DIARY -> R.string.notes_diary
})
private fun typeIcon(type: NotesType) = when (type) {
    NotesType.BUY -> Icons.Outlined.ShoppingBag
    NotesType.TASKS -> Icons.Outlined.Checklist
    NotesType.DIARY -> Icons.AutoMirrored.Outlined.MenuBook
}
@Composable
private fun NotesProblemText(problem: NotesProblem?) {
    if (problem == null) return
    val fallback = when (problem.kind) {
        NotesFailure.AUTH -> R.string.notes_error_auth
        NotesFailure.FORBIDDEN -> R.string.notes_error_forbidden
        NotesFailure.REJECTED -> R.string.notes_error_rejected
        NotesFailure.DELETE_FAILED -> R.string.notes_error_delete
        NotesFailure.NETWORK -> R.string.notes_error_network
        NotesFailure.SERVER -> R.string.notes_error_server
        NotesFailure.DATA -> R.string.notes_error_data
        NotesFailure.CONFIG -> R.string.notes_error_config
        NotesFailure.FOLDER_NOT_EMPTY -> R.string.notes_nonempty
    }
    Text(problem.message ?: stringResource(fallback), color = MaterialTheme.colorScheme.error,
        modifier = Modifier.semantics { liveRegion = LiveRegionMode.Polite })
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
internal fun NotesContent(controller: NotesController, onAuthenticationRequired: () -> Unit = {},
                          onRootChanged: (Boolean) -> Unit = {}, initialFolderId: Long? = null,
                          initialCreate: Boolean = false, initialFolderForm: Boolean = false) {
    val state by controller.state.collectAsState()
    var discard by remember { mutableStateOf<(() -> Unit)?>(null) }
    var foldersVisible by rememberSaveable { mutableStateOf(true) }
    var initialHandled by rememberSaveable { mutableStateOf(false) }
    val editor = state.itemDraft != null || state.folderDraft != null
    val root = !editor && state.selectedFolderId == null
    LaunchedEffect(root) { onRootChanged(root) }
    LifecycleEventEffect(Lifecycle.Event.ON_RESUME) { controller.refresh() }
    LaunchedEffect(state.authenticationRequired) { if (state.authenticationRequired) onAuthenticationRequired() }
    LaunchedEffect(state.fresh, initialHandled) {
        if (state.fresh && !initialHandled) {
            initialHandled = true
            if (initialFolderId != null) controller.selectFolder(initialFolderId)
            if (initialCreate && initialFolderId != null) controller.openItem()
            if (initialFolderForm) controller.openFolderForm()
        }
    }
    fun navigate(action: () -> Unit) {
        if (!state.saving) { if (state.dirty) discard = action else action() }
    }
    val back: () -> Unit = {
        navigate {
            if (editor) controller.closeEditor(discard = true)
            else controller.selectFolder(null, discard = true)
        }
    }
    BackHandler(enabled = !root) { back() }
    Scaffold(topBar = {
        TopAppBar(title = { Text(stringResource(if (state.folderDraft != null) {
            if (state.folderEditId == null) R.string.notes_new_folder else R.string.notes_edit_folder
        } else if (state.itemDraft != null) R.string.notes_edit_item else R.string.notes_title)) },
            navigationIcon = { if (!root) IconButton(onClick = back, enabled = !state.saving) {
                Icon(Icons.AutoMirrored.Filled.ArrowBack, stringResource(R.string.notes_back))
            } }, actions = {
                IconButton(onClick = controller::refresh, enabled = !state.saving && !state.refreshing) {
                    Icon(Icons.Outlined.Refresh, stringResource(R.string.notes_refresh))
                }
            })
    }) { padding ->
        Column(Modifier.fillMaxSize().padding(padding).imePadding()) {
            if (state.saving || state.refreshing) LinearProgressIndicator(Modifier.fillMaxWidth())
            // Notices scroll with each pane so large text does not consume all available height.
            BoxWithConstraints(Modifier.weight(1f)) {
                val wide = maxWidth >= 840.dp
                if (wide) {
                    Row(Modifier.fillMaxSize()) {
                        if (foldersVisible) {
                            FolderNavigator(state, controller, Modifier.width(280.dp),
                                onSelect = { id -> navigate { controller.selectFolder(id, discard = true) } },
                                onNew = { navigate { controller.openFolderForm(discard = true) } },
                                onHide = { foldersVisible = false })
                            VerticalDivider()
                        }
                        Column(Modifier.weight(1f)) {
                            if (!foldersVisible) TextButton(onClick = { foldersVisible = true }) { Text(stringResource(R.string.notes_show_folders)) }
                            Row(Modifier.weight(1f)) {
                                ItemPane(state, controller, Modifier.weight(1f),
                                    onOpen = { navigate { controller.openItem(it, discard = true) } },
                                    onNew = { navigate { controller.openItem(discard = true) } },
                                    onConfigure = { navigate { controller.openFolderForm(edit = true, discard = true) } },
                                    onChild = { navigate { controller.openFolderForm(child = true, discard = true) } })
                                if (editor) {
                                    VerticalDivider()
                                    EditorPane(state, controller, Modifier.weight(1f), back)
                                }
                            }
                        }
                    }
                } else when {
                    editor -> EditorPane(state, controller, Modifier.fillMaxSize(), back)
                    state.selectedFolderId == null -> FolderNavigator(state, controller, Modifier.fillMaxSize(),
                        onSelect = { controller.selectFolder(it) }, onNew = { controller.openFolderForm() })
                    else -> ItemPane(state, controller, Modifier.fillMaxSize(),
                        onOpen = { controller.openItem(it) }, onNew = { controller.openItem() },
                        onConfigure = { controller.openFolderForm(edit = true) }, onChild = { controller.openFolderForm(child = true) })
                }
            }
        }
    }
    discard?.let { action ->
        AlertDialog(onDismissRequest = { discard = null }, title = { Text(stringResource(R.string.notes_discard_title)) },
            text = { Text(stringResource(R.string.notes_discard_message)) },
            confirmButton = { TextButton(onClick = { discard = null; action() }) { Text(stringResource(R.string.notes_discard)) } },
            dismissButton = { TextButton(onClick = { discard = null }) { Text(stringResource(R.string.notes_cancel)) } })
    }
    state.deletion?.let { target ->
        AlertDialog(onDismissRequest = controller::cancelDelete, title = { Text(stringResource(R.string.notes_delete_title)) },
            text = { Text(when (target) {
                is NotesDeletion.Item -> stringResource(R.string.notes_delete_item_message, target.title)
                is NotesDeletion.Folder -> stringResource(R.string.notes_delete_folder_message, target.name)
            }) }, confirmButton = {
                TextButton(onClick = controller::confirmDelete, enabled = state.editable) {
                    Text(stringResource(R.string.notes_confirm_delete), color = MaterialTheme.colorScheme.error)
                }
            }, dismissButton = { TextButton(onClick = controller::cancelDelete) { Text(stringResource(R.string.notes_cancel)) } })
    }
}

@Composable
private fun LoadNotices(state: NotesState, controller: NotesController) {
    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        if (!state.canWrite) Text(stringResource(R.string.notes_read_only), style = MaterialTheme.typography.bodyMedium)
        if (state.saving) Text(stringResource(R.string.notes_saving))
        else if (state.refreshing) Text(stringResource(R.string.notes_loading))
        if (!state.fresh && state.loaded && !state.refreshing) Text(stringResource(R.string.notes_stale))
        state.notice?.let {
            Text(stringResource(when (it) {
                NotesNotice.SAVED -> if (state.loadError != null) R.string.notes_saved_refresh_failed else R.string.notes_saved
                NotesNotice.DELETED -> R.string.notes_deleted
                NotesNotice.UNCERTAIN -> R.string.notes_uncertain
            }), Modifier.semantics { liveRegion = LiveRegionMode.Polite })
        }
        NotesProblemText(state.loadError)
        NotesProblemText(state.problem)
        if (state.reorderFailed) Text(stringResource(R.string.notes_reorder_failed), Modifier.semantics { liveRegion = LiveRegionMode.Polite })
        if (state.fields.isNotEmpty()) Text(stringResource(R.string.notes_invalid), color = MaterialTheme.colorScheme.error)
        if (state.loadError != null || state.uncertain) OutlinedButton(onClick = controller::refresh, enabled = !state.saving && !state.refreshing) {
            Text(stringResource(R.string.notes_retry))
        }
        if (state.uncertain) OutlinedButton(onClick = controller::acknowledgeUncertain, enabled = state.canReview) { Text(stringResource(R.string.notes_reviewed)) }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun FolderNavigator(state: NotesState, controller: NotesController, modifier: Modifier,
                            onSelect: (Long) -> Unit, onNew: () -> Unit, onHide: (() -> Unit)? = null) {
    val listState = rememberLazyListState()
    var preview by remember { mutableStateOf<NotesSiblingOrder?>(null) }
    var dragging by remember { mutableStateOf(false) }
    var dragParent by remember { mutableStateOf<Long?>(null) }
    val rows = (preview?.let { state.tree.withFolderOrder(it) } ?: state.tree).folderRows()
    val currentRows by rememberUpdatedState(rows)
    val currentState by rememberUpdatedState(state)
    LaunchedEffect(state.tree, state.saving, state.refreshing, dragging) {
        if (!dragging && !state.saving && !state.refreshing) preview = null
    }
    val reorderState = rememberReorderableLazyListState(listState) { from, to ->
        val source = currentRows.firstOrNull { it.folder.id == from.key }?.folder
        val target = currentRows.firstOrNull { it.folder.id == to.key }?.folder
        if (currentState.canReorder && source != null && target != null && source.parentId == target.parentId) {
            val ids = preview?.takeIf { it.parentId == source.parentId }?.ids
                ?: currentState.tree.folderSiblings(source.parentId).map { it.id }
            preview = NotesSiblingOrder(source.parentId, movedNotesIds(ids, source.id, target.id))
        }
    }
    PullToRefreshBox(isRefreshing = state.refreshing, onRefresh = controller::refresh, modifier = modifier) {
        LazyColumn(Modifier.fillMaxSize().testTag("notes_folder_navigator"), state = listState, contentPadding = PaddingValues(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
            item(key = "folders-header") {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(stringResource(R.string.notes_folders), style = MaterialTheme.typography.titleLarge, modifier = Modifier.semantics { heading() })
                    Text(stringResource(R.string.notes_shared), style = MaterialTheme.typography.bodySmall)
                    LoadNotices(state, controller)
                    if (state.canWrite) Button(onClick = onNew, enabled = state.editable) { Text(stringResource(R.string.notes_new_folder)) }
                    if (onHide != null) TextButton(onClick = onHide) { Text(stringResource(R.string.notes_hide_folders)) }
                }
            }
            if (state.loaded && state.fresh && state.tree.isEmpty()) item { Text(stringResource(R.string.notes_empty_folders)) }
            items(rows, key = { it.folder.id }) { row ->
                val folder = row.folder
                val siblings = state.tree.folderSiblings(folder.parentId).map { it.id }
                val index = siblings.indexOf(folder.id)
                ReorderableItem(reorderState, key = folder.id, enabled = !dragging || folder.parentId == dragParent) { isDragging ->
                Card(onClick = { onSelect(folder.id) }, enabled = !state.saving,
                    modifier = Modifier.fillMaxWidth().padding(start = (row.depth.coerceAtMost(5) * 12).dp)
                        .testTag("notes_folder_${folder.id}").semantics { selected = state.selectedFolderId == folder.id },
                    colors = CardDefaults.cardColors(containerColor = if (state.selectedFolderId == folder.id) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surfaceContainerLow),
                    elevation = CardDefaults.cardElevation(defaultElevation = if (isDragging) 8.dp else 0.dp)) {
                    ListItem(headlineContent = { Text(folder.name) },
                        supportingContent = { Text(typeLabel(folder.type) + " · " + pluralStringResource(R.plurals.notes_count, folder.notes.size, folder.notes.size)) },
                        leadingContent = {
                            val colors = MaterialTheme.colorScheme
                            val tile = when (folder.type) {
                                NotesType.BUY -> colors.secondaryContainer
                                NotesType.TASKS -> colors.tertiaryContainer
                                NotesType.DIARY -> colors.primaryContainer
                            }
                            Surface(color = tile, shape = MaterialTheme.shapes.medium) {
                                Icon(typeIcon(folder.type), null, Modifier.padding(10.dp).size(24.dp))
                            }
                        }, trailingContent = {
                            if (state.canWrite && siblings.size > 1) ReorderHandle(folder.name, "notes_reorder_folder_${folder.id}", state.canReorder,
                                Modifier.draggableHandle(enabled = state.canReorder,
                                    onDragStarted = { dragParent = folder.parentId; dragging = true }, onDragStopped = {
                                        dragging = false
                                        preview?.let { controller.reorderFolders(it.parentId, it.ids) }
                                    }), index > 0, index < siblings.lastIndex,
                                onUp = { controller.reorderFolders(folder.parentId, movedNotesIds(siblings, folder.id, siblings[index - 1])) },
                                onDown = { controller.reorderFolders(folder.parentId, movedNotesIds(siblings, folder.id, siblings[index + 1])) })
                        }, colors = ListItemDefaults.colors(containerColor = Color.Transparent))
                }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun ItemPane(state: NotesState, controller: NotesController, modifier: Modifier, onOpen: (NotesItem) -> Unit,
                     onNew: () -> Unit, onConfigure: () -> Unit, onChild: () -> Unit) {
    val folder = state.selectedFolder
    val listState = rememberLazyListState()
    var preview by remember(folder?.id) { mutableStateOf<List<Long>?>(null) }
    var dragging by remember(folder?.id) { mutableStateOf(false) }
    val byId = folder?.notes.orEmpty().associateBy { it.id }
    val notes = preview?.mapNotNull { byId[it] } ?: folder?.notes.orEmpty()
    val currentState by rememberUpdatedState(state)
    LaunchedEffect(folder?.notes, state.saving, state.refreshing, dragging) {
        if (!dragging && !state.saving && !state.refreshing) preview = null
    }
    val reorderState = rememberReorderableLazyListState(listState) { from, to ->
        val fromId = from.key as? Long
        val toId = to.key as? Long
        if (currentState.canReorder && fromId != null && toId != null) {
            preview = movedNotesIds(preview ?: currentState.selectedFolder?.notes.orEmpty().map { it.id }, fromId, toId)
        }
    }
    PullToRefreshBox(isRefreshing = state.refreshing, onRefresh = controller::refresh, modifier = modifier) {
        LazyColumn(Modifier.fillMaxSize().testTag("notes_item_list"), state = listState, contentPadding = PaddingValues(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
            item(key = "items-header") {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    LoadNotices(state, controller)
                    if (folder == null) Text(stringResource(R.string.notes_choose_folder))
                    else {
                        Text(folder.name, style = MaterialTheme.typography.headlineSmall, modifier = Modifier.semantics { heading() })
                        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Surface(color = MaterialTheme.colorScheme.secondaryContainer, shape = MaterialTheme.shapes.small) {
                                Text(typeLabel(folder.type), Modifier.padding(horizontal = 10.dp, vertical = 4.dp))
                            }
                            Text(pluralStringResource(R.plurals.notes_count, folder.notes.size, folder.notes.size), Modifier.padding(vertical = 4.dp))
                        }
                        if (state.canWrite) {
                            Button(onClick = onNew, enabled = state.editable) { Text(stringResource(if (folder.type == NotesType.DIARY) R.string.notes_new_note else R.string.notes_new_item)) }
                            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                TextButton(onClick = onConfigure, enabled = state.editable) { Text(stringResource(R.string.notes_edit_folder)) }
                                TextButton(onClick = onChild, enabled = state.editable) { Text(stringResource(R.string.notes_subfolder)) }
                                TextButton(onClick = controller::requestDeleteFolder, enabled = state.editable && !state.dirty) {
                                    Text(stringResource(R.string.notes_delete_folder), color = MaterialTheme.colorScheme.error)
                                }
                            }
                        }
                    }
                }
            }
            if (folder != null && folder.notes.isEmpty() && state.fresh) item { Text(stringResource(R.string.notes_empty_items)) }
            items(notes, key = { it.id }) { note ->
                val ids = folder?.notes.orEmpty().map { it.id }
                val index = ids.indexOf(note.id)
                ReorderableItem(reorderState, key = note.id) { isDragging ->
                Card(onClick = { onOpen(note) }, enabled = !state.saving, modifier = Modifier.fillMaxWidth().testTag("notes_item_${note.id}"),
                    elevation = CardDefaults.cardElevation(defaultElevation = if (isDragging) 8.dp else 0.dp)) {
                    ListItem(headlineContent = { Text(note.title) }, supportingContent = {
                        Column {
                            if (folder?.type == NotesType.DIARY) Text(stringResource(R.string.notes_updated, note.localUpdated()))
                            else {
                                Text(stringResource(if (folder?.type == NotesType.BUY) {
                                    if (note.completed) R.string.notes_purchased else R.string.notes_not_purchased
                                } else if (note.completed) R.string.notes_done else R.string.notes_pending))
                                if (folder?.type == NotesType.TASKS && note.endDate != null) Text(stringResource(R.string.notes_due,
                                    LocalDate.parse(note.endDate).format(DateTimeFormatter.ofLocalizedDate(FormatStyle.MEDIUM))))
                            }
                        }
                    }, trailingContent = {
                        Row {
                        if (folder?.type != NotesType.DIARY) {
                            val label = stringResource(if (folder?.type == NotesType.BUY) R.string.notes_purchased else R.string.notes_done)
                            val description = stringResource(R.string.notes_toggle, label, note.title)
                            Checkbox(checked = note.completed, onCheckedChange = { controller.toggle(note, it) },
                                enabled = state.editable && !state.dirty, modifier = Modifier.semantics { contentDescription = description })
                        }
                        if (state.canWrite && ids.size > 1) ReorderHandle(note.title, "notes_reorder_item_${note.id}", state.canReorder,
                            Modifier.draggableHandle(enabled = state.canReorder,
                                onDragStarted = { dragging = true }, onDragStopped = {
                                    dragging = false
                                    preview?.let { folder?.id?.let { folderId -> controller.reorderItems(folderId, it) } }
                                }), index > 0, index < ids.lastIndex,
                            onUp = { folder?.id?.let { controller.reorderItems(it, movedNotesIds(ids, note.id, ids[index - 1])) } },
                            onDown = { folder?.id?.let { controller.reorderItems(it, movedNotesIds(ids, note.id, ids[index + 1])) } })
                        }
                    })
                }
                }
            }
        }
    }
}

@Composable
private fun ReorderHandle(name: String, tag: String, enabled: Boolean, modifier: Modifier,
                          canMoveUp: Boolean, canMoveDown: Boolean, onUp: () -> Unit, onDown: () -> Unit) {
    var expanded by remember { mutableStateOf(false) }
    val up = stringResource(R.string.notes_move_up)
    val down = stringResource(R.string.notes_move_down)
    Box {
        IconButton(onClick = { expanded = true }, enabled = enabled,
            modifier = modifier.testTag(tag).semantics {
                customActions = if (!enabled) emptyList() else buildList {
                    if (canMoveUp) add(CustomAccessibilityAction(up) { onUp(); true })
                    if (canMoveDown) add(CustomAccessibilityAction(down) { onDown(); true })
                }
            }) { Icon(Icons.Outlined.DragHandle, stringResource(R.string.notes_reorder, name)) }
        DropdownMenu(expanded = expanded && enabled, onDismissRequest = { expanded = false }) {
            DropdownMenuItem(text = { Text(up) }, enabled = canMoveUp, onClick = { expanded = false; onUp() })
            DropdownMenuItem(text = { Text(down) }, enabled = canMoveDown, onClick = { expanded = false; onDown() })
        }
    }
}

@Composable
private fun Choice(label: String, value: String, choices: List<Pair<String, () -> Unit>>, enabled: Boolean) {
    var expanded by remember { mutableStateOf(false) }
    Column {
        OutlinedButton(onClick = { expanded = true }, enabled = enabled, modifier = Modifier.fillMaxWidth()) { Text("$label: $value") }
        DropdownMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
            choices.forEach { (text, action) -> DropdownMenuItem(text = { Text(text) }, onClick = { expanded = false; action() }) }
        }
    }
}
@Composable
private fun EditorPane(state: NotesState, controller: NotesController, modifier: Modifier, onClose: () -> Unit) {
    val editable = state.canWrite && !state.saving
    Column(modifier.testTag("notes_editor").verticalScroll(rememberScrollState()).padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
        LoadNotices(state, controller)
        state.folderDraft?.let { draft ->
            OutlinedTextField(draft.name, { controller.folderInput(draft.copy(name = it)) }, label = { Text(stringResource(R.string.notes_name)) },
                modifier = Modifier.fillMaxWidth(), readOnly = !editable, isError = "name" in state.fields)
            Choice(stringResource(R.string.notes_type), typeLabel(draft.type), NotesType.entries.map { type ->
                typeLabel(type) to { controller.folderInput(draft.copy(type = type)) }
            }, editable)
            PositionField(draft.position, "position" in state.fields, editable) { controller.folderInput(draft.copy(position = it)) }
            if (state.canWrite) Button(onClick = controller::saveFolder, enabled = state.editable) { Text(stringResource(R.string.notes_save)) }
        }
        state.itemDraft?.let { draft ->
            val type = state.folders.firstOrNull { it.folder.id == draft.folderId }?.folder?.type ?: NotesType.DIARY
            Text(typeLabel(type), style = MaterialTheme.typography.titleMedium)
            OutlinedTextField(draft.title, { controller.itemInput(draft.copy(title = it)) }, label = { Text(stringResource(R.string.notes_item_title)) },
                modifier = Modifier.fillMaxWidth(), readOnly = !editable, isError = "title" in state.fields)
            if (type == NotesType.TASKS) {
                OutlinedTextField(draft.description, { controller.itemInput(draft.copy(description = it)) }, label = { Text(stringResource(R.string.notes_description)) },
                    modifier = Modifier.fillMaxWidth(), minLines = 3, readOnly = !editable)
                EndDateField(draft, state, controller, editable)
            }
            if (type != NotesType.DIARY) {
                Row {
                    Checkbox(draft.completed, { controller.itemInput(draft.copy(completed = it)) }, enabled = editable)
                    Text(stringResource(if (type == NotesType.BUY) R.string.notes_purchased else R.string.notes_done), Modifier.padding(top = 12.dp))
                }
            } else DiaryFields(draft, state, controller, editable)
            PositionField(draft.position, "position" in state.fields, editable) { controller.itemInput(draft.copy(position = it)) }
            Choice(stringResource(R.string.notes_destination), state.folders.firstOrNull { it.folder.id == draft.folderId }?.path.orEmpty(),
                state.folders.map { row -> row.path to { controller.itemInput(draft.copy(folderId = row.folder.id)) } }, editable)
            if (state.canWrite) FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                Button(onClick = controller::saveItem, enabled = state.editable) { Text(stringResource(R.string.notes_save)) }
                if (state.selectedItemId != null) TextButton(onClick = controller::requestDeleteItem, enabled = state.editable) {
                    Text(stringResource(R.string.notes_delete), color = MaterialTheme.colorScheme.error)
                }
            }
        }
        TextButton(onClick = onClose, enabled = !state.saving) { Text(stringResource(R.string.notes_close)) }
    }
}
@Composable
private fun PositionField(value: String, error: Boolean, editable: Boolean, onChange: (String) -> Unit) {
    OutlinedTextField(value, onChange, label = { Text(stringResource(R.string.notes_position)) }, modifier = Modifier.fillMaxWidth(),
        singleLine = true, readOnly = !editable, isError = error, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number))
}
@Composable
private fun EndDateField(draft: NotesItemDraft, state: NotesState, controller: NotesController, editable: Boolean) {
    val context = LocalContext.current
    OutlinedTextField(draft.endDate, { controller.itemInput(draft.copy(endDate = it)) }, label = { Text(stringResource(R.string.notes_end_date)) },
        modifier = Modifier.fillMaxWidth(), singleLine = true, readOnly = !editable, isError = "endDate" in state.fields)
    if (state.canWrite) FlowRow {
        TextButton(onClick = {
            val date = runCatching { LocalDate.parse(draft.endDate) }.getOrDefault(LocalDate.now())
            DatePickerDialog(context, { _, year, month, day -> controller.itemInput(draft.copy(endDate = LocalDate.of(year, month + 1, day).toString())) },
                date.year, date.monthValue - 1, date.dayOfMonth).show()
        }, enabled = editable) { Text(stringResource(R.string.notes_pick_date)) }
        TextButton(onClick = { controller.itemInput(draft.copy(endDate = "")) }, enabled = editable) { Text(stringResource(R.string.notes_clear_date)) }
    }
}
@Composable
private fun DiaryFields(draft: NotesItemDraft, state: NotesState, controller: NotesController, editable: Boolean) {
    val style = draft.style
    OutlinedTextField(draft.content, { controller.itemInput(draft.copy(content = it)) }, label = { Text(stringResource(R.string.notes_content)) },
        modifier = Modifier.fillMaxWidth(), minLines = 5, readOnly = !editable)
    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        FilterChip(selected = style.bold, onClick = { controller.itemInput(draft.copy(style = style.copy(bold = !style.bold))) }, enabled = editable,
            label = { Text(stringResource(R.string.notes_bold)) })
        FilterChip(selected = style.italic, onClick = { controller.itemInput(draft.copy(style = style.copy(italic = !style.italic))) }, enabled = editable,
            label = { Text(stringResource(R.string.notes_italic)) })
    }
    OutlinedTextField(style.textColor, { controller.itemInput(draft.copy(style = style.copy(textColor = it))) }, label = { Text(stringResource(R.string.notes_text_color)) },
        modifier = Modifier.fillMaxWidth(), readOnly = !editable, isError = "style" in state.fields)
    OutlinedTextField(style.backgroundColor, { controller.itemInput(draft.copy(style = style.copy(backgroundColor = it))) }, label = { Text(stringResource(R.string.notes_background_color)) },
        modifier = Modifier.fillMaxWidth(), readOnly = !editable, isError = "style" in state.fields)
    Choice(stringResource(R.string.notes_font_size), style.fontSize.toString(), listOf(14, 16, 18, 20, 24).map { size ->
        size.toString() to { controller.itemInput(draft.copy(style = style.copy(fontSize = size))) }
    }, editable)
    Text(stringResource(R.string.notes_preview), style = MaterialTheme.typography.titleMedium)
    val background = runCatching { Color(android.graphics.Color.parseColor(style.backgroundColor)) }.getOrDefault(MaterialTheme.colorScheme.surface)
    val foreground = runCatching { Color(android.graphics.Color.parseColor(style.textColor)) }.getOrDefault(MaterialTheme.colorScheme.onSurface)
    Surface(color = background, shape = MaterialTheme.shapes.medium, modifier = Modifier.fillMaxWidth()) {
        Text(draft.content.ifEmpty { stringResource(R.string.notes_preview_empty) }, Modifier.padding(16.dp), color = foreground,
            fontSize = style.fontSize.coerceIn(1, 200).sp, fontWeight = if (style.bold) FontWeight.Bold else FontWeight.Normal,
            fontStyle = if (style.italic) FontStyle.Italic else FontStyle.Normal)
    }
}

package com.elialombardi.piccistodo.ui.viewmodels

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.elialombardi.piccistodo.data.local.SettingsManager
import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.repository.*
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.distinctUntilChanged
import javax.inject.Inject

sealed interface NotesDeletion {
    data class Item(val id: Long, val title: String) : NotesDeletion
    data class Folder(val id: Long, val name: String) : NotesDeletion
}
enum class NotesNotice { SAVED, DELETED, UNCERTAIN }
data class NotesState(
    val tree: List<NotesFolder> = emptyList(), val loaded: Boolean = false, val fresh: Boolean = false,
    val refreshing: Boolean = false, val saving: Boolean = false, val canWrite: Boolean = false,
    val selectedFolderId: Long? = null, val selectedItemId: Long? = null,
    val itemDraft: NotesItemDraft? = null, val originalItem: NotesItemDraft? = null,
    val folderDraft: NotesFolderDraft? = null, val originalFolder: NotesFolderDraft? = null,
    val folderEditId: Long? = null, val parentId: Long? = null,
    val fields: Set<String> = emptySet(), val problem: NotesProblem? = null, val loadError: NotesProblem? = null,
    val notice: NotesNotice? = null, val uncertain: Boolean = false, val reorderFailed: Boolean = false,
    val authenticationRequired: Boolean = false, val deletion: NotesDeletion? = null
) {
    val folders get() = tree.folderRows()
    val selectedFolder get() = folders.firstOrNull { it.folder.id == selectedFolderId }?.folder
    val dirty get() = (itemDraft != null && itemDraft != originalItem) || (folderDraft != null && folderDraft != originalFolder)
    val editable get() = canWrite && fresh && !saving && !refreshing && !uncertain && !authenticationRequired
    val canReorder get() = editable && itemDraft == null && folderDraft == null
    val canReview get() = uncertain && fresh && !saving && !refreshing
}

class NotesController(private val source: NotesDataSource, private val scope: CoroutineScope,
                      private val expireSession: suspend () -> Unit = {}) {
    private val mutable = MutableStateFlow(NotesState())
    val state = mutable.asStateFlow()
    private var fetch: Job? = null
    private var mutation: Job? = null
    private var generation = 0
    private fun change(block: (NotesState) -> NotesState) { mutable.value = block(mutable.value) }
    fun sessionChanged(role: String?, authenticated: Boolean) {
        generation++; fetch?.cancel(); mutation?.cancel()
        mutable.value = NotesState(canWrite = role == "Writer" || role == "Admin", authenticationRequired = !authenticated)
        if (authenticated) refresh()
    }
    private suspend fun authenticate(problem: NotesProblem): Boolean {
        if (problem.kind != NotesFailure.AUTH) return false
        generation++
        mutable.value = NotesState(authenticationRequired = true)
        expireSession()
        return true
    }
    fun refresh() {
        if (state.value.saving || state.value.authenticationRequired) return
        fetch?.cancel()
        val version = ++generation
        change { it.copy(refreshing = true, fresh = false) }
        fetch = scope.launch {
            try {
                val tree = source.tree()
                if (version != generation) return@launch
                change { current ->
                    val folder = tree.folderRows().firstOrNull { it.folder.id == current.selectedFolderId }?.folder
                    val item = folder?.notes?.firstOrNull { it.id == current.selectedItemId }
                    val replaceEditor = current.itemDraft != null && current.selectedItemId != null && !current.dirty
                    current.copy(tree = tree, loaded = true, fresh = true, refreshing = false, loadError = null,
                        selectedFolderId = folder?.id,
                        selectedItemId = if (replaceEditor) item?.id else current.selectedItemId,
                        itemDraft = if (replaceEditor) item?.let(NotesItemDraft::from) else current.itemDraft,
                        originalItem = if (replaceEditor) item?.let(NotesItemDraft::from) else current.originalItem)
                }
            } catch (error: Exception) {
                if (version != generation) return@launch
                val problem = notesProblem(error)
                if (!authenticate(problem)) change { it.copy(refreshing = false, fresh = false, loadError = problem) }
            }
        }
    }
    // UI confirms discard before calling navigation methods; controller also refuses silent loss.
    fun selectFolder(id: Long?, discard: Boolean = false) {
        if (state.value.saving || (state.value.dirty && !discard)) return
        if (id != null && state.value.folders.none { it.folder.id == id }) return
        change { it.copy(selectedFolderId = id, selectedItemId = null, itemDraft = null, originalItem = null,
            folderDraft = null, originalFolder = null, fields = emptySet(), problem = null) }
    }
    fun openItem(item: NotesItem? = null, discard: Boolean = false) {
        val current = state.value
        if (current.saving || (current.dirty && !discard)) return
        val folder = current.selectedFolder ?: return
        if (item != null && folder.notes.none { it.id == item.id }) return
        if (item == null && !current.editable) return
        val draft = item?.let(NotesItemDraft::from) ?: NotesItemDraft(folder.id)
        change { it.copy(selectedItemId = item?.id, itemDraft = draft, originalItem = draft,
            folderDraft = null, originalFolder = null, fields = emptySet(), problem = null) }
    }
    fun openFolderForm(edit: Boolean = false, child: Boolean = false, discard: Boolean = false) {
        val current = state.value
        if (!current.editable || (current.dirty && !discard)) return
        val folder = current.selectedFolder
        if ((edit || child) && folder == null) return
        val draft = if (edit) NotesFolderDraft(folder!!.name, folder.type, folder.position.toString()) else NotesFolderDraft()
        change { it.copy(folderDraft = draft, originalFolder = draft, folderEditId = if (edit) folder!!.id else null,
            parentId = if (child) folder!!.id else null, itemDraft = null, originalItem = null, selectedItemId = null,
            fields = emptySet(), problem = null) }
    }
    fun closeEditor(discard: Boolean = false) {
        if (state.value.saving || (state.value.dirty && !discard)) return
        change { it.copy(itemDraft = null, originalItem = null, selectedItemId = null, folderDraft = null,
            originalFolder = null, fields = emptySet(), problem = null) }
    }
    fun itemInput(value: NotesItemDraft) { if (state.value.canWrite && !state.value.saving) change { it.copy(itemDraft = value, fields = emptySet()) } }
    fun folderInput(value: NotesFolderDraft) { if (state.value.canWrite && !state.value.saving) change { it.copy(folderDraft = value, fields = emptySet()) } }
    fun saveItem() {
        val current = state.value
        val draft = current.itemDraft ?: return
        if (!current.editable) return
        val errors = draft.errors(current.folders).let {
            if (current.selectedItemId != null && draft.style == current.originalItem?.style) it - "style" else it
        }
        if (errors.isNotEmpty()) { change { it.copy(fields = errors) }; return }
        val type = current.folders.first { it.folder.id == draft.folderId }.folder.type
        val body = NotesWrites.item(draft, if (current.selectedItemId == null) null else current.originalItem, type)
        if (body.size() == 0) return
        mutate {
            val saved = source.saveItem(current.selectedItemId, body)
            if (generation == it) {
                val savedDraft = NotesItemDraft.from(saved)
                change { state -> state.copy(selectedFolderId = saved.folderId, selectedItemId = saved.id,
                    itemDraft = savedDraft, originalItem = savedDraft, notice = NotesNotice.SAVED) }
            }
        }
    }
    fun saveFolder() {
        val current = state.value
        val draft = current.folderDraft ?: return
        if (!current.editable) return
        val errors = draft.errors()
        if (errors.isNotEmpty()) { change { it.copy(fields = errors) }; return }
        val body = NotesWrites.folder(draft, if (current.folderEditId == null) null else current.originalFolder, current.parentId)
        if (body.size() == 0) return
        mutate {
            val id = source.saveFolder(current.folderEditId, body)
            if (generation == it) change { state -> state.copy(selectedFolderId = id, folderDraft = null,
                originalFolder = null, selectedItemId = null, itemDraft = null, originalItem = null, notice = NotesNotice.SAVED) }
        }
    }
    fun toggle(item: NotesItem, completed: Boolean) {
        val current = state.value
        if (!current.editable || current.dirty || current.selectedFolder?.type == NotesType.DIARY ||
            current.selectedFolder?.notes?.none { it.id == item.id } != false) return
        mutate { version ->
            source.saveItem(item.id, NotesWrites.completion(completed))
            if (version == generation) change { it.copy(notice = NotesNotice.SAVED) }
        }
    }
    fun reorderFolders(parentId: Long?, ids: List<Long>) {
        val current = state.value
        if (!current.canReorder) return
        val siblings = current.tree.folderSiblings(parentId)
        reorder(siblings.map { it.id to it.position }, ids, folders = true)
    }
    fun reorderItems(folderId: Long, ids: List<Long>) {
        val current = state.value
        if (!current.canReorder || current.selectedFolderId != folderId) return
        reorder(current.selectedFolder?.notes.orEmpty().map { it.id to it.position }, ids, folders = false)
    }
    private fun reorder(siblings: List<Pair<Long, Int>>, ids: List<Long>, folders: Boolean) {
        val original = siblings.map { it.first }
        if (ids == original || ids.size != original.size || ids.toSet() != original.toSet()) return
        val positions = siblings.toMap()
        val updates = ids.mapIndexedNotNull { index, id -> if (positions[id] != index) id to index else null }
        mutate { version ->
            try {
                for ((id, position) in updates) {
                    if (version != generation) return@mutate
                    try {
                        if (folders) source.saveFolder(id, NotesWrites.position(position))
                        else source.saveItem(id, NotesWrites.position(position))
                    } catch (_: NotesWriteConfirmedException) {
                        // HTTP success is confirmed; response content is not needed for a position write.
                    }
                }
                if (version == generation) change { it.copy(notice = NotesNotice.SAVED) }
            } catch (error: Exception) {
                if (version == generation) change { it.copy(reorderFailed = true) }
                throw error
            }
        }
    }
    fun requestDeleteItem() {
        val current = state.value
        if (!current.editable) return
        val item = current.selectedFolder?.notes?.firstOrNull { it.id == current.selectedItemId } ?: return
        change { it.copy(deletion = NotesDeletion.Item(item.id, item.title)) }
    }
    fun requestDeleteFolder() {
        val current = state.value
        val folder = current.selectedFolder ?: return
        if (!current.editable || current.dirty) return
        if (folder.children.isNotEmpty() || folder.notes.isNotEmpty()) {
            change { it.copy(problem = NotesProblem(NotesFailure.FOLDER_NOT_EMPTY)) }; return
        }
        change { it.copy(deletion = NotesDeletion.Folder(folder.id, folder.name)) }
    }
    fun cancelDelete() { if (!state.value.saving) change { it.copy(deletion = null) } }
    fun confirmDelete() {
        if (!state.value.editable) return
        when (val target = state.value.deletion) {
            is NotesDeletion.Item -> mutate { version ->
                source.deleteItem(target.id)
                if (version == generation) change { it.copy(itemDraft = null, originalItem = null, selectedItemId = null, notice = NotesNotice.DELETED) }
            }
            is NotesDeletion.Folder -> mutate { version ->
                // Refuse a folder that became nonempty since confirmation. No recursive deletion.
                val latest = source.tree().folderRows().firstOrNull { it.folder.id == target.id }?.folder
                if (latest == null || latest.notes.isNotEmpty() || latest.children.isNotEmpty()) {
                    if (version == generation) change { it.copy(problem = NotesProblem(NotesFailure.FOLDER_NOT_EMPTY)) }
                } else {
                    source.deleteFolder(target.id)
                    if (version == generation) change { it.copy(selectedFolderId = null, notice = NotesNotice.DELETED) }
                }
            }
            null -> Unit
        }
    }
    fun acknowledgeUncertain() {
        if (state.value.canReview) change { it.copy(uncertain = false, notice = null, problem = null) }
    }
    private fun mutate(action: suspend (Int) -> Unit) {
        if (!state.value.editable) return
        fetch?.cancel()
        val version = ++generation
        change { it.copy(saving = true, fresh = false, refreshing = false, deletion = null, problem = null, notice = null, reorderFailed = false) }
        mutation = scope.launch {
            try { action(version) }
            catch (error: Exception) {
                if (version != generation) return@launch
                if (error is NotesWriteConfirmedException) {
                    // The server accepted the write but its response could not identify the saved item.
                    // Close the draft rather than leave a duplicate-create action available.
                    change { it.copy(notice = NotesNotice.SAVED, itemDraft = null, originalItem = null,
                        folderDraft = null, originalFolder = null, selectedItemId = null,
                        problem = NotesProblem(NotesFailure.DATA)) }
                    return@launch
                }
                val problem = notesProblem(error, writing = true)
                if (authenticate(problem)) return@launch
                change { it.copy(problem = problem, uncertain = problem.uncertain,
                    canWrite = it.canWrite && problem.kind != NotesFailure.FORBIDDEN,
                    notice = if (problem.uncertain) NotesNotice.UNCERTAIN else null) }
            } finally {
                if (version == generation) {
                    change { it.copy(saving = false) }; refresh()
                }
            }
        }
    }
}
@HiltViewModel
class NotesViewModel @Inject constructor(source: NotesRepository, settings: SettingsManager) : ViewModel() {
    val controller = NotesController(source, viewModelScope) { settings.clearSession() }
    init {
        viewModelScope.launch {
            settings.sessionFlow.distinctUntilChanged().collect { (token, _, role) -> controller.sessionChanged(role, token != null) }
        }
    }
}

package com.elialombardi.piccistodo.ui.viewmodels

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.elialombardi.piccistodo.data.local.SettingsManager
import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.repository.*
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import javax.inject.Inject

data class TasksState(
    val tasks: List<Task> = emptyList(), val projects: List<Project> = emptyList(),
    val tasksLoaded: Boolean = false, val projectsLoaded: Boolean = false,
    val refreshing: Boolean = false, val saving: Boolean = false,
    val taskError: TaskProblem? = null, val projectError: TaskProblem? = null,
    val problem: TaskProblem? = null, val authenticationRequired: Boolean = false,
    val selected: Task? = null, val draft: TaskDraft? = null, val original: TaskDraft? = null,
    val editId: String? = null, val fields: Set<String> = emptySet(),
    val projectForm: Boolean = false, val projectName: String = "", val projectDescription: String = "",
    val projectProblem: TaskProblem? = null, val projectNameInvalid: Boolean = false,
    val uncertain: Boolean = false
)

/** No disk task cache or offline writes. Each navigation entry owns a fresh controller. */
class TasksController(
    private val source: TaskDataSource,
    private val scope: CoroutineScope,
    private val expireSession: suspend () -> Unit = {}
) {
    private val mutable = MutableStateFlow(TasksState())
    val state = mutable.asStateFlow()
    private var fetch: Job? = null
    private var generation = 0
    private fun change(block: (TasksState) -> TasksState) { mutable.value = block(mutable.value) }
    private suspend fun authenticate(problem: TaskProblem): Boolean {
        if (problem.kind != TaskFailure.AUTH) return false
        generation++
        expireSession()
        mutable.value = TasksState(authenticationRequired = true)
        return true
    }
    fun refresh() {
        if (state.value.saving || state.value.authenticationRequired) return
        fetch?.cancel()
        val version = ++generation
        change { it.copy(refreshing = true) }
        fetch = scope.launch {
            supervisorScope {
                val tasks = async { runCatching { source.tasks() } }
                val projects = async { runCatching { source.projects() } }
                val taskResult = tasks.await()
                val projectResult = projects.await()
                if (version != generation) return@supervisorScope
                val taskError = taskResult.exceptionOrNull()?.let { taskProblem(it as Exception) }
                val projectError = projectResult.exceptionOrNull()?.let { taskProblem(it as Exception) }
                if (taskError?.let { authenticate(it) } == true || projectError?.let { authenticate(it) } == true) return@supervisorScope
                change { current -> current.copy(
                    tasks = taskResult.getOrNull() ?: current.tasks,
                    projects = projectResult.getOrNull()?.sortedWith(compareBy<Project> { it.name }.thenBy { it.id }) ?: current.projects,
                    tasksLoaded = current.tasksLoaded || taskResult.isSuccess,
                    projectsLoaded = current.projectsLoaded || projectResult.isSuccess,
                    taskError = taskError, projectError = projectError, refreshing = false,
                    selected = current.selected?.let { old -> taskResult.getOrNull()?.find { it.id == old.id } ?: if (taskResult.isSuccess) null else old }
                ) }
            }
        }
    }
    fun select(task: Task?) { if (!state.value.saving) change { it.copy(selected = task, problem = null) } }
    fun edit(task: Task? = null) {
        if (state.value.saving) return
        val draft = task?.let(TaskDraft::from) ?: TaskDraft()
        change { it.copy(draft = draft, original = draft, editId = task?.id, fields = emptySet(), problem = null, uncertain = false) }
    }
    fun draft(value: TaskDraft) { if (!state.value.saving) change { it.copy(draft = value, fields = emptySet()) } }
    fun closeForm() { if (!state.value.saving) change { it.copy(draft = null, original = null, problem = null, uncertain = false) } }
    fun openProject() { if (!state.value.saving) change { it.copy(projectForm = true, projectProblem = null, projectNameInvalid = false) } }
    fun projectInput(name: String, description: String) {
        if (!state.value.saving) change { it.copy(projectName = name, projectDescription = description, projectNameInvalid = false) }
    }
    fun closeProject() { if (!state.value.saving) change { it.copy(projectForm = false, projectName = "", projectDescription = "", projectProblem = null) } }
    // Explicit user decision only, after fetching current records. Never automatically replay writes.
    fun acknowledgeUncertain() {
        if (!state.value.refreshing && state.value.taskError == null && state.value.projectError == null)
            change { it.copy(uncertain = false, problem = null, projectProblem = null) }
    }
    private fun mutate(action: suspend () -> Unit, project: Boolean = false) {
        if (state.value.saving || state.value.uncertain || state.value.authenticationRequired) return
        fetch?.cancel()
        generation++
        change { it.copy(saving = true, refreshing = false, problem = null, projectProblem = null) }
        scope.launch {
            try {
                action()
            } catch (error: Exception) {
                val problem = taskProblem(error, writing = true)
                if (!authenticate(problem)) change {
                    if (project) it.copy(projectProblem = problem, uncertain = problem.uncertain)
                    else it.copy(problem = problem, fields = setOfNotNull(problem.field), uncertain = problem.uncertain)
                }
            } finally {
                change { it.copy(saving = false) }
                refresh()
            }
        }
    }
    fun saveTask() {
        val current = state.value
        val draft = current.draft ?: return
        val errors = draft.errors(current.projects)
        if (errors.isNotEmpty()) { change { it.copy(fields = errors) }; return }
        if (!current.projectsLoaded || current.projectError != null) return
        mutate({
            val saved = source.saveTask(current.editId, draft.request())
            change { it.copy(tasks = it.tasks.filterNot { task -> task.id == saved.id } + saved,
                selected = if (current.editId != null) saved else null, draft = null, original = null, problem = null) }
        })
    }
    fun saveProject() {
        val current = state.value
        if (current.projectName.isBlank()) { change { it.copy(projectNameInvalid = true) }; return }
        mutate({
            val saved = source.createProject(ProjectRequest(current.projectName.trim(), current.projectDescription.trim()))
            change { it.copy(projects = (it.projects.filterNot { project -> project.id == saved.id } + saved)
                .sortedWith(compareBy<Project> { project -> project.name }.thenBy { project -> project.id }),
                draft = it.draft?.copy(projectId = saved.id), projectForm = false, projectName = "", projectDescription = "") }
        }, project = true)
    }
    fun status(sentOn: String) {
        val selected = state.value.selected ?: return
        if (sentOn.isNotEmpty() && !validDate(sentOn)) return
        mutate({
            val latest = source.task(selected.id)
            // Legacy unassigned records must be repaired in the full editor.
            if (!validProjectId(latest.projectId.orEmpty()) || state.value.projects.none { it.id == latest.projectId }) {
                change { it.copy(problem = TaskProblem(TaskFailure.PROJECT_MISSING, "projectId")) }
            } else {
                val saved = source.saveTask(latest.id, latest.writable(sentOn))
                change { it.copy(tasks = it.tasks.filterNot { task -> task.id == saved.id } + saved, selected = saved) }
            }
        })
    }
}

@HiltViewModel
class TasksViewModel @Inject constructor(repository: TasksRepository, settings: SettingsManager) : ViewModel() {
    val controller = TasksController(repository, viewModelScope) { settings.clearSession() }
}

package com.elialombardi.piccistodo.ui.viewmodels

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.elialombardi.piccistodo.data.local.SettingsManager
import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.repository.*
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import javax.inject.Inject

data class TasksState(
    val tasks: List<Task> = emptyList(), val projects: List<Project> = emptyList(),
    val tasksLoaded: Boolean = false, val projectsLoaded: Boolean = false,
    val refreshing: Boolean = false, val saving: Boolean = false,
    val taskError: TaskProblem? = null, val projectError: TaskProblem? = null,
    val problem: TaskProblem? = null, val authenticationRequired: Boolean = false,
    val selected: Task? = null, val draft: TaskDraft? = null, val original: TaskDraft? = null,
    val editId: String? = null, val fields: Set<String> = emptySet(),
    val projectForm: Boolean = false, val projectName: String = "", val projectDescription: String = "",
    val projectProblem: TaskProblem? = null, val projectNameInvalid: Boolean = false,
    val uncertain: Boolean = false
)

/** No disk task cache or offline writes. Each navigation entry owns a fresh controller. */
class TasksController(
    private val source: TaskDataSource,
    private val scope: CoroutineScope,
    private val expireSession: suspend () -> Unit = {}
) {
    private val mutable = MutableStateFlow(TasksState())
    val state = mutable.asStateFlow()
    private var fetch: Job? = null
    private var generation = 0
    private fun change(block: (TasksState) -> TasksState) { mutable.value = block(mutable.value) }
    private suspend fun authenticate(problem: TaskProblem): Boolean {
        if (problem.kind != TaskFailure.AUTH) return false
        generation++
        expireSession()
        mutable.value = TasksState(authenticationRequired = true)
        return true
    }
    fun refresh() {
        if (state.value.saving || state.value.authenticationRequired) return
        fetch?.cancel()
        val version = ++generation
        change { it.copy(refreshing = true) }
        fetch = scope.launch {
            supervisorScope {
                val tasks = async { runCatching { source.tasks() } }
                val projects = async { runCatching { source.projects() } }
                val taskResult = tasks.await()
                val projectResult = projects.await()
                if (version != generation) return@supervisorScope
                val taskError = taskResult.exceptionOrNull()?.let { taskProblem(it as Exception) }
                val projectError = projectResult.exceptionOrNull()?.let { taskProblem(it as Exception) }
                if (taskError?.let { authenticate(it) } == true || projectError?.let { authenticate(it) } == true) return@supervisorScope
                change { current -> current.copy(
                    tasks = taskResult.getOrNull() ?: current.tasks,
                    projects = projectResult.getOrNull()?.sortedWith(compareBy<Project> { it.name }.thenBy { it.id }) ?: current.projects,
                    tasksLoaded = current.tasksLoaded || taskResult.isSuccess,
                    projectsLoaded = current.projectsLoaded || projectResult.isSuccess,
                    taskError = taskError, projectError = projectError, refreshing = false,
                    selected = current.selected?.let { old -> taskResult.getOrNull()?.find { it.id == old.id } ?: if (taskResult.isSuccess) null else old }
                ) }
            }
        }
    }
    fun select(task: Task?) { if (!state.value.saving) change { it.copy(selected = task, problem = null) } }
    fun edit(task: Task? = null) {
        if (state.value.saving) return
        val draft = task?.let(TaskDraft::from) ?: TaskDraft()
        change { it.copy(draft = draft, original = draft, editId = task?.id, fields = emptySet(), problem = null) }
    }
    fun draft(value: TaskDraft) { if (!state.value.saving) change { it.copy(draft = value, fields = emptySet()) } }
    fun closeForm() { if (!state.value.saving) change { it.copy(draft = null, original = null, problem = null) } }
    fun openProject() { if (!state.value.saving) change { it.copy(projectForm = true, projectProblem = null, projectNameInvalid = false) } }
    fun projectInput(name: String, description: String) {
        if (!state.value.saving) change { it.copy(projectName = name, projectDescription = description, projectNameInvalid = false) }
    }
    fun closeProject() { if (!state.value.saving) change { it.copy(projectForm = false, projectName = "", projectDescription = "", projectProblem = null) } }
    // Explicit user decision only, after fetching current records. Never automatically replay writes.
    fun acknowledgeUncertain() {
        if (!state.value.refreshing && state.value.tasksLoaded && state.value.projectsLoaded &&
            state.value.taskError == null && state.value.projectError == null)
            change { it.copy(uncertain = false, problem = null, projectProblem = null) }
    }
    private fun mutate(action: suspend () -> Unit, project: Boolean = false) {
        if (state.value.saving || state.value.uncertain || state.value.authenticationRequired) return
        fetch?.cancel()
        generation++
        change { it.copy(saving = true, refreshing = false, problem = null, projectProblem = null) }
        scope.launch {
            try {
                action()
            } catch (error: Exception) {
                val problem = taskProblem(error, writing = true)
                if (!authenticate(problem)) change {
                    if (project) it.copy(projectProblem = problem, uncertain = problem.uncertain)
                    else it.copy(problem = problem, fields = setOfNotNull(problem.field), uncertain = problem.uncertain)
                }
            } finally {
                change { it.copy(saving = false) }
                refresh()
            }
        }
    }
    fun saveTask() {
        val current = state.value
        val draft = current.draft ?: return
        val errors = draft.errors(current.projects)
        if (errors.isNotEmpty()) { change { it.copy(fields = errors) }; return }
        if (!current.projectsLoaded || current.projectError != null) return
        mutate({
            val saved = source.saveTask(current.editId, draft.request())
            change { it.copy(tasks = it.tasks.filterNot { task -> task.id == saved.id } + saved,
                selected = if (current.editId != null) saved else null, draft = null, original = null, problem = null) }
        })
    }
    fun saveProject() {
        val current = state.value
        if (current.projectName.isBlank()) { change { it.copy(projectNameInvalid = true) }; return }
        mutate({
            val saved = source.createProject(ProjectRequest(current.projectName.trim(), current.projectDescription.trim()))
            change { it.copy(projects = (it.projects.filterNot { project -> project.id == saved.id } + saved)
                .sortedWith(compareBy<Project> { project -> project.name }.thenBy { project -> project.id }),
                draft = it.draft?.copy(projectId = saved.id), projectForm = false, projectName = "", projectDescription = "") }
        }, project = true)
    }
    fun status(sentOn: String) {
        val selected = state.value.selected ?: return
        if (sentOn.isNotEmpty() && !validDate(sentOn)) return
        mutate({
            val latest = source.task(selected.id)
            // Legacy unassigned records must be repaired in the full editor.
            if (!validProjectId(latest.projectId.orEmpty()) || state.value.projects.none { it.id == latest.projectId }) {
                change { it.copy(problem = TaskProblem(TaskFailure.PROJECT_MISSING, "projectId")) }
            } else {
                val saved = source.saveTask(latest.id, latest.writable(sentOn))
                change { it.copy(tasks = it.tasks.filterNot { task -> task.id == saved.id } + saved, selected = saved) }
            }
        })
    }
}

@HiltViewModel
class TasksViewModel @Inject constructor(repository: TasksRepository, settings: SettingsManager) : ViewModel() {
    val controller = TasksController(repository, viewModelScope) { settings.clearSession() }
}

package com.elialombardi.piccistodo

import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.repository.*
import com.google.gson.JsonParser
import kotlinx.coroutines.runBlocking
import mockwebserver3.MockResponse
import mockwebserver3.MockWebServer
import org.junit.Assert.*
import org.junit.Test
import retrofit2.HttpException
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import java.time.ZoneId
import java.util.Locale

class NotesContractTest {
    private val itemJson = """{"id":42,"folderId":12,"position":2,"title":"Collect parcel","content":"Diary text","description":"Code","endDate":"2026-11-14","completed":true,"style":{"bold":true,"italic":false,"textColor":"#123456","backgroundColor":"#ffffff","fontSize":20},"createdAt":"2026-11-10T00:40:00.123456+02:00","updatedAt":"2026-11-10T00:40:00.123456+02:00"}"""
    private fun json(raw: String) = JsonParser.parseString(raw)
    private val item get() = NotesDecoder.item(json(itemJson))

    @Test fun completionAndExplicitFalseNeverOverwriteHiddenFields() {
        listOf(true, false).forEach { value ->
            val body = NotesWrites.completion(value)
            assertEquals(setOf("completed"), body.keySet())
            assertEquals(value, body["completed"].asBoolean)
        }
    }
    @Test fun movingAndRenamingOnlySendChangedFieldsAcrossAllTypes() {
        val original = NotesItemDraft.from(item)
        NotesType.entries.forEach { type ->
            val body = NotesWrites.item(original.copy(folderId = 15, title = "New title", position = "0"), original, type)
            assertEquals(setOf("folderId", "title", "position"), body.keySet())
            assertEquals(15, body["folderId"].asInt)
            assertEquals(0, body["position"].asInt)
            assertFalse(body.has("style")); assertFalse(body.has("content")); assertFalse(body.has("description"))
        }
    }
    @Test fun dateClearingAndStyleReplacementPreserveUntouchedProperties() {
        val original = NotesItemDraft.from(item)
        val cleared = NotesWrites.item(original.copy(endDate = "", description = "", completed = false), original, NotesType.TASKS)
        assertEquals("", cleared["endDate"].asString)
        assertFalse(cleared["endDate"].isJsonNull)
        assertEquals("", cleared["description"].asString)
        assertFalse(cleared["completed"].asBoolean)
        val style = NotesWrites.item(original.copy(style = original.style.copy(italic = true)), original, NotesType.DIARY)["style"].asJsonObject
        assertEquals(5, style.size()); assertTrue(style["bold"].asBoolean)
        assertTrue(style["italic"].asBoolean); assertEquals("#123456", style["textColor"].asString)
        assertEquals(20, style["fontSize"].asInt)
    }
    @Test fun typedCreateAndIndependentDiaryFolderDefaults() {
        val draft = NotesItemDraft(12, "Milk")
        assertEquals(setOf("folderId", "title", "position", "completed"), NotesWrites.item(draft, null, NotesType.BUY).keySet())
        assertEquals(setOf("folderId", "title", "position", "completed", "description"), NotesWrites.item(draft, null, NotesType.TASKS).keySet())
        assertEquals(setOf("folderId", "title", "position", "content", "style"), NotesWrites.item(draft, null, NotesType.DIARY).keySet())
        val child = NotesWrites.folder(NotesFolderDraft("Child"), null, 12)
        assertEquals("diary", child["type"].asString); assertEquals(12, child["parentId"].asInt)
        val root = NotesWrites.folder(NotesFolderDraft("Root"), null, null)
        assertFalse(root.has("parentId")); assertEquals(0, root["position"].asInt)
        val patch = NotesWrites.folder(NotesFolderDraft("Root", NotesType.BUY, "0"), NotesFolderDraft("Root", position = "2"), null)
        assertEquals(setOf("type", "position"), patch.keySet())
    }
    @Test fun calendarAndPositionValidationDoesNotInventDateOrdering() {
        assertTrue(notesDateValid("2024-02-29")); assertTrue(notesDateValid("2000-01-01")); assertTrue(notesDateValid(""))
        listOf("2026-02-29", "2026-11-31", "2026-1-01", "2026-11-14T00:00:00Z").forEach { assertFalse(notesDateValid(it)) }
        listOf("-1", "1.5", "1e2", "", "9999999999999").forEach { assertNull(notesPosition(it)) }
        assertEquals(0, notesPosition("0"))
        assertTrue(NotesFolderDraft("   ").errors().contains("name"))
        assertTrue(NotesFolderDraft("a".repeat(101)).errors().contains("name"))
        assertTrue(NotesItemDraft(12, "x".repeat(201)).errors(emptyList()).contains("title"))
    }
    @Test fun numericIdsDefaultsDirectChildrenAndServerOrderArePreserved() {
        val second = itemJson.replace("\"id\":42", "\"id\":7")
        val childNote = itemJson.replace("\"id\":42", "\"id\":99").replace("\"folderId\":12", "\"folderId\":13")
        val tree = NotesDecoder.tree(json("""[{"id":12,"name":"Legacy","position":0,"parentId":null,"notes":[$itemJson,$second],"children":[{"id":13,"name":"Child","type":"buy_list","position":0,"parentId":12,"notes":[$childNote],"children":[]}]}]"""))
        assertEquals(NotesType.DIARY, tree.first().type)
        assertEquals(listOf(42L, 7L), tree.first().notes.map { it.id })
        assertEquals(2, tree.first().notes.size); assertEquals(1, tree.first().children.first().notes.size)
        assertEquals(listOf(0, 1), tree.folderRows().map { it.depth })
        val defaults = NotesDecoder.item(json(itemJson).asJsonObject.apply { remove("style"); remove("description"); remove("completed"); remove("endDate") })
        assertEquals(NotesStyle(), defaults.style); assertFalse(defaults.completed); assertNull(defaults.endDate)
        assertThrows(NotesDataException::class.java) { NotesDecoder.item(json(itemJson.replace("\"id\":42", "\"id\":\"42\""))) }
        assertThrows(NotesDataException::class.java) { NotesDecoder.item(json(itemJson.replace("2026-11-14", "2026-02-29"))) }
        assertThrows(NotesDataException::class.java) { NotesDecoder.tree(json("""[{"id":12,"name":"X","type":"invalid"}]""")) }
    }
    @Test fun endDateNeverShiftsWhileTimestampsUseDeviceZone() {
        assertEquals("2026-11-14", NotesItemDraft.from(item).endDate)
        assertTrue(item.localUpdated(ZoneId.of("America/Los_Angeles"), Locale.US).contains("Nov 9, 2026"))
        assertTrue(item.localUpdated(ZoneId.of("Asia/Tokyo"), Locale.US).contains("Nov 10, 2026"))
        assertEquals(123456000, item.updatedAt.nano)
    }
    private suspend fun withServer(block: suspend (MockWebServer, NotesHttpDataSource) -> Unit) {
        MockWebServer().use { server ->
            server.start()
            val api = Retrofit.Builder().baseUrl(server.url("/"))
                .addConverterFactory(GsonConverterFactory.create()).build().create(NotesApi::class.java)
            block(server, NotesHttpDataSource { api })
        }
    }
    @Test fun realHttpUsesNumericIdsPartialBodiesAndExactSuccessCodes() = runBlocking {
        withServer { server, source ->
            server.enqueue(MockResponse.Builder().code(201).body(itemJson).build())
            assertEquals(42L, source.saveItem(null, NotesWrites.item(NotesItemDraft(12, "New"), null, NotesType.BUY)).id)
            val create = server.takeRequest()
            assertEquals("/api/notes", create.url.encodedPath)
            val body = json(create.body!!.utf8()).asJsonObject
            assertFalse(body.has("id")); assertFalse(body.has("updatedAt")); assertFalse(body.has("style"))
            server.enqueue(MockResponse.Builder().code(200).body(itemJson).build())
            source.saveItem(42, NotesWrites.completion(false))
            val patch = server.takeRequest()
            assertEquals("PUT", patch.method); assertEquals("/api/notes/42", patch.url.encodedPath)
            assertEquals("{\"completed\":false}", patch.body!!.utf8())
            server.enqueue(MockResponse.Builder().code(200).body("{\"id\":12,\"children\":[],\"notes\":[]}").build())
            assertEquals(12L, source.saveFolder(12, NotesWrites.folder(NotesFolderDraft("New"), NotesFolderDraft("Old"), null)))
            server.takeRequest()
            server.enqueue(MockResponse.Builder().code(204).build()); source.deleteItem(42)
            assertEquals("/api/notes/42", server.takeRequest().url.encodedPath)
            server.enqueue(MockResponse.Builder().code(204).build()); source.deleteFolder(12)
            assertEquals("/api/note-folders/12", server.takeRequest().url.encodedPath)
            server.enqueue(MockResponse.Builder().code(200).body("[]").build()); assertTrue(source.tree().isEmpty())
            assertEquals("/api/note-folders/tree", server.takeRequest().url.encodedPath)
        }
    }
    @Test fun jsonErrorsAndNonJsonFallbacksDoNotMisclassify404Or400() = runBlocking {
        withServer { server, source ->
            listOf(400 to NotesFailure.REJECTED, 422 to NotesFailure.REJECTED, 401 to NotesFailure.AUTH,
                404 to NotesFailure.DELETE_FAILED, 500 to NotesFailure.SERVER).forEach { (code, expected) ->
                val jsonError = code != 401
                server.enqueue(MockResponse.Builder().code(code).addHeader("Content-Type", if (jsonError) "application/json" else "text/plain")
                    .body(if (jsonError) "{\"error\":\"Service rejected change\"}" else "not JSON").build())
                val error = try { source.deleteItem(42); error("Expected error") } catch (error: HttpException) { error }
                val problem = notesProblem(error, writing = true)
                assertEquals(expected, problem.kind)
                assertEquals(if (jsonError) "Service rejected change" else null, problem.message)
            }
        }
    }
    @Test fun malformedConfirmedCreateIsNotReportedAsAnUnconfirmedSave() = runBlocking {
        withServer { server, source ->
            server.enqueue(MockResponse.Builder().code(201).body("not-json").build())
            try {
                source.saveItem(null, NotesWrites.completion(false)); fail("Expected confirmed response error")
            } catch (_: NotesWriteConfirmedException) { /* known saved, reconcile instead of resubmit */ }
        }
    }
}

package com.elialombardi.piccistodo

import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.repository.*
import com.elialombardi.piccistodo.ui.viewmodels.*
import com.google.gson.JsonObject
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import org.junit.Assert.*
import org.junit.Test
import okhttp3.ResponseBody.Companion.toResponseBody
import retrofit2.HttpException
import retrofit2.Response
import java.io.IOException
import java.time.OffsetDateTime

@OptIn(ExperimentalCoroutinesApi::class)
class NotesControllerTest {
    private val date = OffsetDateTime.parse("2026-11-10T00:40:00Z")
    private fun item(id: Long, folder: Long) = NotesItem(id, folder, 2, "Item $id", "Diary content", "Separate description",
        "2026-11-14", true, NotesStyle(bold = true, textColor = "#123456", fontSize = 24), date, date)
    private fun initial() = listOf(
        NotesFolder(12, "Root", NotesType.DIARY, 0, null,
            listOf(NotesFolder(13, "Child", NotesType.TASKS, 0, 12, emptyList(), listOf(item(43, 13)))), listOf(item(42, 12))),
        NotesFolder(15, "Buy", NotesType.BUY, 0, null, emptyList(), emptyList()),
        NotesFolder(16, "Empty", NotesType.DIARY, 0, null, emptyList(), emptyList()))
    private inner class Source : NotesDataSource {
        var folders = initial()
        var calls = 0
        var deletes = 0
        var failLoad = false
        var failWrite: Exception? = null
        var gate: CompletableDeferred<Unit>? = null
        var fetchOverride: (suspend () -> List<NotesFolder>)? = null
        var last: JsonObject? = null
        var afterWrite: () -> Unit = {}
        fun transform(block: (NotesFolder) -> NotesFolder) {
            fun walk(rows: List<NotesFolder>): List<NotesFolder> = rows.map { block(it.copy(children = walk(it.children))) }
            folders = walk(folders)
        }
        override suspend fun tree(): List<NotesFolder> {
            fetchOverride?.let { return it() }
            if (failLoad) throw IOException()
            return folders
        }
        override suspend fun saveFolder(id: Long?, body: JsonObject): Long {
            calls++; last = body.deepCopy(); gate?.await(); failWrite?.let { throw it }
            val target = id ?: 100L
            if (id == null) {
                val new = NotesFolder(target, body["name"].asString, NotesType.parse(body["type"].asString), body["position"].asInt,
                    body["parentId"]?.asLong, emptyList(), emptyList())
                if (new.parentId == null) folders = folders + new
                else transform { if (it.id == new.parentId) it.copy(children = it.children + new) else it }
            } else transform { if (it.id == id) it.copy(name = body["name"]?.asString ?: it.name,
                type = body["type"]?.asString?.let(NotesType::parse) ?: it.type, position = body["position"]?.asInt ?: it.position) else it }
            afterWrite(); return target
        }
        override suspend fun saveItem(id: Long?, body: JsonObject): NotesItem {
            calls++; last = body.deepCopy(); gate?.await(); failWrite?.let { throw it }
            val old = folders.folderRows().flatMap { it.folder.notes }.firstOrNull { it.id == id } ?: item(200, body["folderId"].asLong)
            val saved = old.copy(folderId = body["folderId"]?.asLong ?: old.folderId,
                title = body["title"]?.asString ?: old.title, position = body["position"]?.asInt ?: old.position,
                description = body["description"]?.asString ?: old.description, content = body["content"]?.asString ?: old.content,
                endDate = if (body.has("endDate")) body["endDate"].asString.takeIf { it.isNotEmpty() } else old.endDate,
                completed = body["completed"]?.asBoolean ?: old.completed)
            transform { folder -> folder.copy(notes = folder.notes.filterNot { it.id == saved.id } + if (folder.id == saved.folderId) listOf(saved) else emptyList()) }
            afterWrite(); return saved
        }
        override suspend fun deleteItem(id: Long) {
            deletes++; failWrite?.let { throw it }; transform { it.copy(notes = it.notes.filterNot { note -> note.id == id }) }
        }
        override suspend fun deleteFolder(id: Long) {
            deletes++; failWrite?.let { throw it }; folders = folders.filterNot { it.id == id }
        }
    }
    private fun NotesController.current() = state.value

    @Test fun directItemsFolderSelectionAndCancelCreationPreserveSelection() = runTest {
        val source = Source(); val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle()
        c.selectFolder(12); assertEquals(listOf(42L), c.current().selectedFolder!!.notes.map { it.id })
        c.openItem(c.current().selectedFolder!!.notes.first()); assertEquals(42L, c.current().selectedItemId)
        c.selectFolder(13); assertNull(c.current().itemDraft)
        assertEquals(listOf(43L), c.current().selectedFolder!!.notes.map { it.id })
        c.openFolderForm(); c.closeEditor(); assertEquals(13L, c.current().selectedFolderId)
        c.openFolderForm(child = true); assertEquals(13L, c.current().parentId)
        assertEquals(NotesType.DIARY, c.current().folderDraft!!.type)
    }
    @Test fun dirtyDraftCannotDisappearWithoutExplicitDiscard() = runTest {
        val c = NotesController(Source(), this); c.sessionChanged("Writer", true); advanceUntilIdle()
        c.selectFolder(12); c.openItem(); c.itemInput(c.current().itemDraft!!.copy(title = "Unsaved"))
        c.selectFolder(13); c.closeEditor()
        assertEquals(12L, c.current().selectedFolderId); assertEquals("Unsaved", c.current().itemDraft!!.title)
        c.selectFolder(13, discard = true); assertNull(c.current().itemDraft)
    }
    @Test fun typeChangesAndMovesNeverRewriteHiddenItemFields() = runTest {
        val source = Source(); val before = source.folders.first().notes.first()
        val c = NotesController(source, this); c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(12)
        listOf(NotesType.BUY, NotesType.TASKS, NotesType.DIARY).forEach { type ->
            c.openFolderForm(edit = true); c.folderInput(c.current().folderDraft!!.copy(type = type)); c.saveFolder(); advanceUntilIdle()
            assertEquals(before, c.current().selectedFolder!!.notes.first())
            assertEquals(NotesType.TASKS, c.current().selectedFolder!!.children.first().type)
            assertEquals(setOf("type"), source.last!!.keySet())
        }
        c.openItem(before); c.itemInput(c.current().itemDraft!!.copy(folderId = 15)); c.saveItem(); advanceUntilIdle()
        assertEquals(15L, c.current().selectedFolderId); assertEquals(42L, c.current().selectedItemId)
        assertEquals(setOf("folderId"), source.last!!.keySet())
        val moved = c.current().selectedFolder!!.notes.first()
        assertEquals(before.copy(folderId = 15), moved)
        c.itemInput(c.current().itemDraft!!.copy(folderId = 12)); c.saveItem(); advanceUntilIdle()
        assertEquals(before, c.current().selectedFolder!!.notes.first())
    }
    @Test fun completionOnlyFalseAndDateClearingRefreshAndReselect() = runTest {
        val source = Source(); val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(13)
        c.toggle(c.current().selectedFolder!!.notes.first(), false); advanceUntilIdle()
        assertEquals("{\"completed\":false}", source.last.toString())
        val saved = c.current().selectedFolder!!.notes.first()
        assertEquals("Diary content", saved.content); assertFalse(saved.completed)
        c.openItem(saved); c.itemInput(c.current().itemDraft!!.copy(endDate = "")); c.saveItem(); advanceUntilIdle()
        assertEquals("{\"endDate\":\"\"}", source.last.toString()); assertNull(c.current().selectedFolder!!.notes.first().endDate)
        assertEquals(43L, c.current().selectedItemId)
    }
    @Test fun readerCanBrowseButCannotModifyOrToggle() = runTest {
        val source = Source(); val c = NotesController(source, this)
        c.sessionChanged("Reader", true); advanceUntilIdle(); c.selectFolder(13)
        val row = c.current().selectedFolder!!.notes.first(); c.openItem(row)
        c.itemInput(c.current().itemDraft!!.copy(title = "No")); c.saveItem(); c.toggle(row, false)
        c.openFolderForm(); c.requestDeleteItem(); c.confirmDelete(); advanceUntilIdle()
        assertEquals("Item 43", c.current().itemDraft!!.title); assertEquals(0, source.calls + source.deletes)
    }
    @Test fun duplicateCreateAndSavedButRefreshFailedNeverReplay() = runTest {
        val source = Source(); val c = NotesController(source, this)
        c.sessionChanged("Admin", true); advanceUntilIdle(); c.selectFolder(15); c.openItem()
        c.itemInput(c.current().itemDraft!!.copy(title = "Milk")); source.gate = CompletableDeferred()
        source.afterWrite = { source.failLoad = true }
        c.saveItem(); c.saveItem(); runCurrent(); assertEquals(1, source.calls)
        source.gate!!.complete(Unit); advanceUntilIdle()
        assertEquals(NotesNotice.SAVED, c.current().notice); assertNotNull(c.current().loadError)
        assertFalse(c.current().editable); assertEquals(200L, c.current().selectedItemId)
        source.failLoad = false; c.refresh(); advanceUntilIdle()
        assertEquals(1, source.calls); assertEquals(200L, c.current().selectedFolder!!.notes.first().id)
    }
    @Test fun failedAndUncertainSavesKeepInputAndRequireReview() = runTest {
        val source = Source(); val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(15); c.openItem()
        c.itemInput(c.current().itemDraft!!.copy(title = "Keep draft")); source.failWrite = IOException()
        c.saveItem(); advanceUntilIdle()
        assertEquals("Keep draft", c.current().itemDraft!!.title); assertTrue(c.current().uncertain)
        c.saveItem(); advanceUntilIdle(); assertEquals(1, source.calls)
        c.acknowledgeUncertain(); assertFalse(c.current().uncertain)
        assertEquals("Keep draft", c.current().itemDraft!!.title)
    }
    @Test fun emptyOnlyFolderDeletionAndItemConfirmationCancellation() = runTest {
        val source = Source(); val c = NotesController(source, this)
        c.sessionChanged("Admin", true); advanceUntilIdle(); c.selectFolder(12); c.requestDeleteFolder()
        assertEquals(NotesFailure.FOLDER_NOT_EMPTY, c.current().problem!!.kind); assertNull(c.current().deletion)
        c.openItem(c.current().selectedFolder!!.notes.first()); c.requestDeleteItem(); c.cancelDelete(); c.confirmDelete()
        assertEquals(0, source.deletes)
        c.requestDeleteItem(); c.confirmDelete(); advanceUntilIdle(); assertEquals(1, source.deletes)
        assertNull(c.current().itemDraft); assertTrue(c.current().selectedFolder!!.notes.isEmpty())
        c.selectFolder(16); c.requestDeleteFolder(); c.cancelDelete(); c.confirmDelete(); assertEquals(1, source.deletes)
        c.requestDeleteFolder(); c.confirmDelete(); advanceUntilIdle(); assertEquals(2, source.deletes)
        assertNull(c.current().selectedFolderId)
    }
    @Test fun folderThatBecameNonemptyIsNotDeleted() = runTest {
        val source = Source(); val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(16); c.requestDeleteFolder()
        source.transform { if (it.id == 16L) it.copy(notes = listOf(item(88, 16))) else it }
        c.confirmDelete(); advanceUntilIdle()
        assertEquals(0, source.deletes); assertEquals(NotesFailure.FOLDER_NOT_EMPTY, c.current().problem!!.kind)
    }
    @Test fun oldFetchAndAccountChangesCannotRestorePreviousClientState() = runTest {
        val source = Source(); val c = NotesController(source, this)
        val old = CompletableDeferred<List<NotesFolder>>()
        source.fetchOverride = { withContext(NonCancellable) { old.await() } }
        c.sessionChanged("Writer", true); runCurrent()
        source.fetchOverride = null; source.folders = emptyList()
        c.sessionChanged("Reader", true); advanceUntilIdle()
        old.complete(initial()); advanceUntilIdle()
        assertTrue(c.current().tree.isEmpty()); assertFalse(c.current().canWrite)
        c.sessionChanged(null, false); assertFalse(c.current().loaded); assertTrue(c.current().authenticationRequired)
    }
    @Test fun failedInitialLoadIsNotSuccessfulEmptyAndInvalidDraftSendsNothing() = runTest {
        val source = Source().apply { failLoad = true }; val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle()
        assertFalse(c.current().loaded); assertNotNull(c.current().loadError); assertFalse(c.current().editable)
        source.failLoad = false; c.refresh(); advanceUntilIdle(); c.selectFolder(13); c.openItem()
        c.itemInput(c.current().itemDraft!!.copy(title = " ", position = "-1", endDate = "2026-02-29")); c.saveItem()
        assertTrue(c.current().fields.containsAll(listOf("title", "position", "endDate"))); assertEquals(0, source.calls)
    }
    @Test fun rootAndChildCreationRefreshAndReselectWithIndependentDiaryType() = runTest {
        val source = Source(); val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(13)
        c.openFolderForm(); c.folderInput(NotesFolderDraft("New root")); c.saveFolder(); advanceUntilIdle()
        assertEquals(100L, c.current().selectedFolderId); assertNull(c.current().folderDraft)
        assertNull(c.current().selectedFolder!!.parentId); assertEquals(NotesType.DIARY, c.current().selectedFolder!!.type)
        assertFalse(source.last!!.has("parentId"))
        source.folders = initial(); c.refresh(); advanceUntilIdle(); c.selectFolder(13)
        c.openFolderForm(child = true); c.folderInput(NotesFolderDraft("New child")); c.saveFolder(); advanceUntilIdle()
        assertEquals(100L, c.current().selectedFolderId); assertEquals(13L, c.current().selectedFolder!!.parentId)
        assertEquals(NotesType.DIARY, c.current().selectedFolder!!.type)
        assertEquals(NotesType.TASKS, c.current().folders.first { it.folder.id == 13L }.folder.type)
    }
    @Test fun rejectedInputIsRetainedButMalformedConfirmedWriteClosesDuplicateCreate() = runTest {
        val source = Source(); val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(15); c.openItem()
        c.itemInput(c.current().itemDraft!!.copy(title = "Kept"))
        source.failWrite = HttpException(Response.error<Unit>(400, "rejected".toResponseBody()))
        c.saveItem(); advanceUntilIdle()
        assertEquals("Kept", c.current().itemDraft!!.title); assertFalse(c.current().uncertain)
        assertEquals(NotesFailure.REJECTED, c.current().problem!!.kind)
        source.failWrite = NotesWriteConfirmedException()
        c.saveItem(); advanceUntilIdle()
        assertEquals(NotesNotice.SAVED, c.current().notice); assertNull(c.current().itemDraft)
        assertFalse(c.current().uncertain); assertEquals(2, source.calls)
    }
    @Test fun authenticationExpiryClearsStateAndDoesNotRetry() = runTest {
        val source = Source(); var expirations = 0
        val c = NotesController(source, this) { expirations++ }
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(12)
        source.fetchOverride = { throw HttpException(Response.error<Unit>(401, "expired".toResponseBody())) }
        c.refresh(); advanceUntilIdle()
        assertEquals(1, expirations); assertTrue(c.current().authenticationRequired)
        assertTrue(c.current().tree.isEmpty()); assertNull(c.current().selectedFolderId)
        c.refresh(); advanceUntilIdle(); assertEquals(1, expirations)
    }
}

package com.elialombardi.piccistodo

import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.repository.*
import com.elialombardi.piccistodo.ui.viewmodels.*
import com.google.gson.JsonObject
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import okhttp3.ResponseBody.Companion.toResponseBody
import org.junit.Assert.*
import org.junit.Test
import retrofit2.HttpException
import retrofit2.Response
import java.io.IOException
import java.time.OffsetDateTime

@OptIn(ExperimentalCoroutinesApi::class)
class NotesReorderingTest {
    private val date = OffsetDateTime.parse("2026-11-10T00:40:00Z")
    private fun note(id: Long, folder: Long, position: Int) = NotesItem(id, folder, position, "Item $id", "Diary content", "Description",
        "2026-12-01", true, NotesStyle(true, true, "#123456", "#abcdef", 24), date, date)
    private fun initialTree() = listOf(
        NotesFolder(12, "Root", NotesType.DIARY, 0, null, listOf(
            NotesFolder(13, "Child", NotesType.TASKS, 0, 12, emptyList(), listOf(note(43, 13, 0), note(44, 13, 1))),
            NotesFolder(14, "Other child", NotesType.DIARY, 1, 12, emptyList(), emptyList())), listOf(note(41, 12, 0), note(42, 12, 1))),
        NotesFolder(15, "Buy", NotesType.BUY, 1, null, emptyList(), listOf(note(45, 15, 0), note(46, 15, 1))),
        NotesFolder(16, "Empty", NotesType.DIARY, 2, null, emptyList(), emptyList()))
    private inner class Source : NotesDataSource {
        var rows = initialTree()
        val writes = mutableListOf<Triple<Boolean, Long, JsonObject>>()
        var failAt: Int? = null
        var failure: Exception = IOException()
        var failRefresh = false
        var gate: CompletableDeferred<Unit>? = null
        var malformedConfirmed = false
        fun transform(block: (NotesFolder) -> NotesFolder) {
            fun walk(rows: List<NotesFolder>): List<NotesFolder> = rows.map { block(it.copy(children = walk(it.children))) }
            rows = walk(rows)
        }
        override suspend fun tree(): List<NotesFolder> {
            if (failRefresh) throw IOException()
            fun sorted(rows: List<NotesFolder>): List<NotesFolder> = rows.sortedWith(compareBy<NotesFolder> { it.position }.thenBy { it.id })
                .map { it.copy(children = sorted(it.children), notes = it.notes.sortedWith(compareBy<NotesItem> { n -> n.position }.thenBy { n -> n.id })) }
            return sorted(rows)
        }
        private suspend fun write(folder: Boolean, id: Long, body: JsonObject) {
            writes += Triple(folder, id, body.deepCopy()); gate?.await()
            if (writes.size == failAt) throw failure
            assertEquals(setOf("position"), body.keySet())
            transform { f -> if (folder && f.id == id) f.copy(position = body["position"].asInt)
                else f.copy(notes = f.notes.map { if (!folder && it.id == id) it.copy(position = body["position"].asInt) else it }) }
            if (malformedConfirmed) throw NotesWriteConfirmedException()
        }
        override suspend fun saveFolder(id: Long?, body: JsonObject): Long { write(true, requireNotNull(id), body); return id }
        override suspend fun saveItem(id: Long?, body: JsonObject): NotesItem {
            write(false, requireNotNull(id), body); return rows.folderRows().flatMap { it.folder.notes }.first { it.id == id }
        }
        override suspend fun deleteFolder(id: Long) = error("Not used")
        override suspend fun deleteItem(id: Long) = error("Not used")
    }
    private fun NotesController.current() = state.value

    @Test fun previewMovesWholeSiblingSubtreesWithoutMovingParentsOrNotes() {
        val before = initialTree()
        val moved = before.withFolderOrder(NotesSiblingOrder(null, listOf(15, 12, 16)))
        assertEquals(listOf(15L, 12L, 16L), moved.map { it.id })
        assertEquals(before.first(), moved[1])
        assertEquals(listOf(15L, 12L, 13L, 14L, 16L), moved.folderRows().map { it.folder.id })
        val children = before.withFolderOrder(NotesSiblingOrder(12, listOf(14, 13)))
        assertEquals(listOf(14L, 13L), children.first().children.map { it.id })
        assertEquals(before.first().notes, children.first().notes)
        assertEquals(before, before.withFolderOrder(NotesSiblingOrder(12, listOf(15, 13))))
        assertEquals(listOf(1L, 3L, 2L), movedNotesIds(listOf(1, 2, 3), 2, 3))
        assertEquals(listOf(1L, 2L), movedNotesIds(listOf(1, 2), 9, 2))
    }

    @Test fun positionPayloadContainsOnlyExplicitNumericPositionIncludingZero() {
        assertEquals("{\"position\":0}", NotesWrites.position(0).toString())
        assertEquals("{\"position\":2}", NotesWrites.position(2).toString())
        assertThrows(IllegalArgumentException::class.java) { NotesWrites.position(-1) }
    }

    @Test fun rootAndNestedReordersPersistOnlyPositionsAndKeepSelectedFolder() = runTest {
        val source = Source(); val before = source.rows
        val c = NotesController(source, this); c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(13)
        c.reorderFolders(null, listOf(15, 12, 16)); advanceUntilIdle()
        assertEquals(listOf(15L, 12L, 16L), c.current().tree.map { it.id })
        assertEquals(13L, c.current().selectedFolderId)
        assertEquals(before.first().children, c.current().tree[1].children)
        assertEquals(before.first().notes, c.current().tree[1].notes)
        c.reorderFolders(12, listOf(14, 13)); advanceUntilIdle()
        assertEquals(listOf(14L, 13L), c.current().tree.folderSiblings(12).map { it.id })
        assertTrue(source.writes.all { it.first && it.third.keySet() == setOf("position") })
        assertEquals(NotesNotice.SAVED, c.current().notice)
    }

    @Test fun notesInEveryFolderTypeRetainAllHiddenFieldsAndNeverTouchOtherFolders() = runTest {
        val source = Source(); val c = NotesController(source, this); c.sessionChanged("Admin", true); advanceUntilIdle()
        listOf(12L, 13L, 15L).forEach { folderId ->
            c.selectFolder(folderId)
            val before = c.current().selectedFolder!!.notes
            val others = c.current().folders.filterNot { it.folder.id == folderId }.associate { it.folder.id to it.folder.notes }
            c.reorderItems(folderId, before.map { it.id }.reversed()); advanceUntilIdle()
            val after = c.current().selectedFolder!!.notes
            assertEquals(before.map { it.id }.reversed(), after.map { it.id })
            after.forEach { saved -> assertEquals(before.first { it.id == saved.id }.copy(position = saved.position), saved) }
            others.forEach { (id, notes) -> assertEquals(notes, c.current().folders.first { it.folder.id == id }.folder.notes) }
        }
        assertTrue(source.writes.all { !it.first && it.third.keySet() == setOf("position") })
    }

    @Test fun noOpMissingDuplicateAndCrossParentOrdersAreRejectedWithoutWrites() = runTest {
        val source = Source(); val c = NotesController(source, this); c.sessionChanged("Writer", true); advanceUntilIdle()
        c.reorderFolders(null, listOf(12, 15, 16)); c.reorderFolders(null, listOf(15, 12)); c.reorderFolders(null, listOf(12, 12, 16))
        c.reorderFolders(12, listOf(15, 13)); c.reorderFolders(999, listOf(12)); c.selectFolder(13)
        c.reorderItems(12, listOf(42, 41)); c.reorderItems(13, listOf(44, 45)); c.reorderItems(13, listOf(44, 44))
        advanceUntilIdle(); assertTrue(source.writes.isEmpty())
    }

    @Test fun readersOpenEditorsAndStaleOrUncertainStatesCannotReorder() = runTest {
        val source = Source(); val c = NotesController(source, this); c.sessionChanged("Reader", true); advanceUntilIdle()
        c.reorderFolders(null, listOf(15, 12, 16)); c.selectFolder(13); c.reorderItems(13, listOf(44, 43))
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(13); c.openItem(c.current().selectedFolder!!.notes.first())
        c.reorderItems(13, listOf(44, 43)); c.itemInput(c.current().itemDraft!!.copy(title = "Unsaved"))
        c.reorderFolders(null, listOf(15, 12, 16)); assertEquals("Unsaved", c.current().itemDraft!!.title)
        c.closeEditor(discard = true); source.failRefresh = true; c.refresh(); advanceUntilIdle()
        c.reorderItems(13, listOf(44, 43)); advanceUntilIdle(); assertTrue(source.writes.isEmpty())
    }

    @Test fun repeatedDropsCannotStartOverlappingPositionWrites() = runTest {
        val source = Source().apply { gate = CompletableDeferred() }; val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(13)
        c.reorderItems(13, listOf(44, 43)); c.reorderItems(13, listOf(44, 43)); runCurrent()
        assertEquals(1, source.writes.size); assertTrue(c.current().saving)
        source.gate!!.complete(Unit); advanceUntilIdle()
        assertEquals(2, source.writes.size); assertEquals(listOf(44L, 43L), c.current().selectedFolder!!.notes.map { it.id })
    }

    @Test fun partialFailureStopsAndRefetchesWithoutClaimingCompleteOrReplaying() = runTest {
        val source = Source().apply { failAt = 2; failure = HttpException(Response.error<Unit>(400, "Rejected".toResponseBody())) }
        val c = NotesController(source, this); c.sessionChanged("Writer", true); advanceUntilIdle()
        c.reorderFolders(null, listOf(16, 15, 12)); advanceUntilIdle()
        assertEquals(2, source.writes.size); assertTrue(c.current().reorderFailed)
        assertEquals(NotesFailure.REJECTED, c.current().problem!!.kind); assertNull(c.current().notice)
        assertEquals(source.tree(), c.current().tree); assertTrue(c.current().fresh)
        c.refresh(); advanceUntilIdle(); assertEquals(2, source.writes.size)
    }

    @Test fun uncertainPositionWriteRequiresReviewAndDoesNotReplay() = runTest {
        val source = Source().apply { failAt = 1 }; val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(13)
        c.reorderItems(13, listOf(44, 43)); advanceUntilIdle()
        assertTrue(c.current().uncertain); assertTrue(c.current().reorderFailed)
        c.reorderItems(13, listOf(44, 43)); advanceUntilIdle(); assertEquals(1, source.writes.size)
        c.acknowledgeUncertain(); source.failAt = null; c.reorderItems(13, listOf(44, 43)); advanceUntilIdle()
        assertEquals(listOf(44L, 43L), c.current().selectedFolder!!.notes.map { it.id }); assertFalse(c.current().reorderFailed)
    }

    @Test fun confirmedPositionResponsesNeedNoItemBodyAndFailedRefreshDoesNotReplay() = runTest {
        val source = Source().apply { malformedConfirmed = true }; val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.selectFolder(13)
        source.failRefresh = true; c.reorderItems(13, listOf(44, 43)); advanceUntilIdle()
        assertEquals(2, source.writes.size); assertEquals(NotesNotice.SAVED, c.current().notice)
        assertNotNull(c.current().loadError); assertFalse(c.current().canReorder)
        source.failRefresh = false; c.refresh(); advanceUntilIdle()
        assertEquals(2, source.writes.size); assertEquals(listOf(44L, 43L), c.current().selectedFolder!!.notes.map { it.id })
    }

    @Test fun accountChangeDuringDropCannotContinueWritingTheOldOrder() = runTest {
        val source = Source().apply { gate = CompletableDeferred() }; val c = NotesController(source, this)
        c.sessionChanged("Writer", true); advanceUntilIdle(); c.reorderFolders(null, listOf(16, 15, 12)); runCurrent()
        c.sessionChanged("Reader", true); source.gate!!.complete(Unit); advanceUntilIdle()
        assertEquals(1, source.writes.size); assertFalse(c.current().canReorder); assertFalse(c.current().saving)
    }
}

package com.elialombardi.piccistodo

import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.remote.TasksApi
import com.elialombardi.piccistodo.data.repository.*
import com.google.gson.Gson
import com.google.gson.JsonParser
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.runBlocking
import mockwebserver3.MockResponse
import mockwebserver3.MockWebServer
import org.junit.Assert.*
import org.junit.Test
import retrofit2.HttpException
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import java.io.IOException
import java.math.BigDecimal
import java.time.LocalDate
import java.util.Locale
import java.util.TimeZone

class TasksContractTest {
    private val projectId = "11111111-1111-4111-8111-111111111111"
    private val taskId = "22222222-2222-4222-8222-222222222222"
    private val taskJson = """{"id":"$taskId","projectId":"$projectId","projectName":"Client","name":"Work","cost":120.5,"date":"2026-11-09"}"""
    private val task get() = Gson().fromJson(taskJson, Task::class.java)

    @Test fun statusUsesOnlyNonemptySentDateAndToleratesLegacyOptionalFields() {
        listOf("", ",\"sentOn\":null", ",\"sentOn\":\"\"").forEach { suffix ->
            val row = Gson().fromJson(taskJson.dropLast(1) + suffix + "}", Task::class.java)
            assertFalse(row.isSent); assertEquals("", row.writable().sentOn)
            assertEquals("", row.writable().description)
        }
        assertTrue(task.copy(sentOn = "2026-11-10").isSent)
        val legacy = task.copy(projectId = "", projectName = "")
        assertEquals(BigDecimal("120.5"), listOf(legacy).summary().pendingTotal)
        assertTrue(TaskDraft.from(legacy).errors(emptyList()).contains("projectId"))
    }

    @Test fun summaryIsExactAndIncludesUnassignedAndNegativePendingCosts() {
        val rows = listOf(task.copy(cost = BigDecimal("0.10"), projectId = null),
            task.copy(cost = BigDecimal("0.20")), task.copy(cost = BigDecimal("-0.05")),
            task.copy(cost = BigDecimal("999"), sentOn = "2026-11-01"))
        assertEquals(TaskSummary(3, BigDecimal("0.25"), 4), rows.summary())
        assertEquals(TaskSummary(0, BigDecimal.ZERO, 0), emptyList<Task>().summary())
        assertEquals("€0.25", eur(rows.summary().pendingTotal, Locale.US))
    }

    @Test fun pendingMonthsAndHistoryUseStableUuidStringOrderWithBothStatuses() {
        val a = task.copy(id = "00000000-0000-4000-8000-000000000001", date = "2026-10-01")
        val b = a.copy(id = "ffffffff-ffff-4fff-8fff-ffffffffffff")
        val sent = task.copy(sentOn = "2026-11-10")
        val rows = listOf(sent, b, task, a)
        assertEquals(listOf("2026-10", "2026-11"), rows.pendingByMonth().keys.toList())
        assertEquals(listOf(a, b), rows.pendingByMonth()["2026-10"])
        assertEquals(listOf(sent, task, b, a), rows.history())
    }

    @Test fun decimalCommaAndFiniteNumericValidationDoNotInventNonnegativeRule() {
        assertEquals(BigDecimal("-12.50"), parseCost(" -12,50 "))
        assertEquals(BigDecimal("0.25"), parseCost(".25"))
        listOf("", "NaN", "Infinity", "1,2.3", "1 234,50", "--1", "1e9999", "9".repeat(400)).forEach {
            assertNull(it, parseCost(it))
        }
        val draft = TaskDraft(projectId, " Work ", "12,50", "2026-11-09", description = " Details ")
        val json = Gson().toJsonTree(draft.request()).asJsonObject
        assertEquals(setOf("projectId", "name", "cost", "date", "sentOn", "description"), json.keySet())
        assertTrue(json["cost"].asJsonPrimitive.isNumber)
        assertEquals(BigDecimal("12.50"), json["cost"].asBigDecimal)
        assertEquals("Work", json["name"].asString); assertEquals("Details", json["description"].asString)
        assertEquals("", json["sentOn"].asString)
    }

    @Test fun validationRequiresRealDatesAndProjectButNoDateOrderOrLengthLimits() {
        val project = Project(projectId, "Client")
        val invalid = TaskDraft("bad", "  ", "NaN", "2026-02-29", "2026-11-31")
        assertEquals(setOf("projectId", "name", "cost", "date", "sentOn"), invalid.errors(listOf(project)))
        listOf("2026-1-01", "2026-11-09T00:00:00Z", "", "2026-04-31").forEach { assertFalse(validDate(it)) }
        assertTrue(validDate("2024-02-29"))
        assertTrue(TaskDraft(projectId, "x".repeat(1000), "-1", "2099-12-31", "2000-01-01",
            "x".repeat(10000)).errors(listOf(project)).isEmpty())
        assertEquals("10", TaskDraft().cost); assertEquals("", TaskDraft().projectId)
    }

    @Test fun calendarDatesRemainUnchangedOnBothSidesOfUtc() {
        val original = TimeZone.getDefault()
        try {
            listOf("Pacific/Kiritimati", "America/Los_Angeles", "Asia/Tokyo").forEach { zone ->
                TimeZone.setDefault(TimeZone.getTimeZone(zone))
                assertEquals(LocalDate.now().toString(), TaskDraft().date)
                assertEquals("2026-11-09", TaskDraft.from(task).request().date)
                assertEquals("2026-11-01", task.writable("2026-11-01").sentOn)
            }
        } finally { TimeZone.setDefault(original) }
    }

    private suspend fun withApi(block: suspend (MockWebServer, TasksApi) -> Unit) {
        MockWebServer().use { server ->
            server.start()
            val api = Retrofit.Builder().baseUrl(server.url("/api/"))
                .addConverterFactory(GsonConverterFactory.create()).build().create(TasksApi::class.java)
            block(server, api)
        }
    }

    @Test fun httpArraysCreatedResponsesFullPutAndExplicitClearsFollowExactContract() = runBlocking {
        withApi { server, api ->
            server.enqueue(MockResponse.Builder().code(200).body("[$taskJson]").build())
            assertEquals(taskId, api.tasks().single().id)
            val get = server.takeRequest(); assertEquals("/api/tasks", get.url.encodedPath)
            assertEquals("application/json", get.headers["Accept"])
            server.enqueue(MockResponse.Builder().code(200).body("[]").build())
            assertTrue(api.projects().isEmpty()); assertEquals("/api/projects", server.takeRequest().url.encodedPath)
            server.enqueue(MockResponse.Builder().code(200).body("[]").build())
            assertTrue(api.tasks().isEmpty()); server.takeRequest()
            server.enqueue(MockResponse.Builder().code(201).body(taskJson).build())
            assertEquals(taskId, api.createTask(task.writable()).id)
            val post = server.takeRequest(); assertEquals("POST", post.method)
            assertEquals("/api/tasks", post.url.encodedPath)
            assertTrue(post.headers["Content-Type"]!!.startsWith("application/json"))
            val body = JsonParser.parseString(post.body!!.utf8()).asJsonObject
            assertEquals(setOf("projectId", "name", "cost", "date", "sentOn", "description"), body.keySet())
            assertTrue(body["cost"].asJsonPrimitive.isNumber)
            assertEquals("", body["sentOn"].asString); assertEquals("", body["description"].asString)
            server.enqueue(MockResponse.Builder().code(200).body(taskJson).build())
            api.task(taskId); assertEquals("/api/tasks/$taskId", server.takeRequest().url.encodedPath)
            server.enqueue(MockResponse.Builder().code(200).body(taskJson).build())
            api.updateTask(taskId, task.writable("2026-11-10"))
            val put = server.takeRequest(); assertEquals("PUT", put.method)
            assertEquals("/api/tasks/$taskId", put.url.encodedPath)
            assertEquals("2026-11-10", JsonParser.parseString(put.body!!.utf8()).asJsonObject["sentOn"].asString)
            server.enqueue(MockResponse.Builder().code(201).body("""{"id":"$projectId","name":"Client"}""").build())
            assertEquals(projectId, api.createProject(ProjectRequest("Client", "")).id)
            assertEquals("/api/projects", server.takeRequest().url.encodedPath)
        }
    }

    @Test fun plainTextAndJsonHttpErrorsAreClassifiedWithoutExposingInternals() = runBlocking {
        withApi { server, api ->
            listOf(400 to TaskFailure.VALIDATION, 401 to TaskFailure.AUTH, 403 to TaskFailure.FORBIDDEN,
                404 to TaskFailure.MISSING, 409 to TaskFailure.DUPLICATE, 500 to TaskFailure.SERVER).forEach { (code, expected) ->
                server.enqueue(MockResponse.Builder().code(code).addHeader("Content-Type", "text/plain")
                    .body(if (code == 400) "Name required" else "private database internals").build())
                val error = try { api.createTask(task.writable()); error("Expected HTTP failure") } catch (e: HttpException) { e }
                val problem = taskProblem(error, writing = true)
                assertEquals(expected, problem.kind); assertEquals(code >= 500, problem.uncertain)
                assertEquals(if (code == 400) "name" else null, problem.field)
                server.takeRequest()
            }
            server.enqueue(MockResponse.Builder().code(400).addHeader("Content-Type", "application/json")
                .body("""{"message":"SentOn must be yyyy-MM-dd"}""").build())
            val error = try { api.updateTask(taskId, task.writable()); error("Expected failure") } catch (e: HttpException) { e }
            assertEquals("sentOn", taskProblem(error).field)
        }
    }

    @Test fun uncertainNetworkAndParsingFailuresCannotBeMistakenForSafeResubmission() {
        assertEquals(TaskProblem(TaskFailure.NETWORK, uncertain = true), taskProblem(IOException(), writing = true))
        assertFalse(taskProblem(IOException()).uncertain)
        assertTrue(taskProblem(IllegalStateException("Malformed success response"), writing = true).uncertain)
        assertTrue(taskProblem(IllegalArgumentException("Malformed decimal response"), writing = true).uncertain)
        assertEquals(TaskFailure.CONFIG, taskProblem(TasksConfigurationException(IllegalArgumentException())).kind)
        assertThrows(CancellationException::class.java) { taskProblem(CancellationException()) }
    }
}

package com.elialombardi.piccistodo

import com.elialombardi.piccistodo.data.model.*
import com.elialombardi.piccistodo.data.repository.*
import com.elialombardi.piccistodo.ui.viewmodels.*
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import okhttp3.ResponseBody.Companion.toResponseBody
import org.junit.Assert.*
import org.junit.Test
import retrofit2.HttpException
import retrofit2.Response
import java.io.IOException
import java.math.BigDecimal

@OptIn(ExperimentalCoroutinesApi::class)
class TasksControllerTest {
    private val project = Project("11111111-1111-4111-8111-111111111111", "Client")
    private val row = Task("22222222-2222-4222-8222-222222222222", project.id, project.name,
        "Work", BigDecimal("12.50"), "2026-11-09", description = "Original description")
    private fun http(code: Int, message: String = "Failure") = HttpException(Response.error<Unit>(code, message.toResponseBody()))
    private inner class Source : TaskDataSource {
        var rows = listOf(row)
        var projectRows = listOf(project)
        var taskError: Exception? = null
        var projectError: Exception? = null
        var writeError: Exception? = null
        var detailError: Exception? = null
        var taskFetch: (suspend () -> List<Task>)? = null
        var projectFetch: (suspend () -> List<Project>)? = null
        var gate: CompletableDeferred<Unit>? = null
        var writes = 0
        var reads = 0
        var details = 0
        var last: TaskRequest? = null
        var lastId: String? = null
        var projectRequest: ProjectRequest? = null
        override suspend fun tasks(): List<Task> {
            reads++; taskError?.let { throw it }; return taskFetch?.invoke() ?: rows
        }
        override suspend fun projects(): List<Project> {
            projectError?.let { throw it }; return projectFetch?.invoke() ?: projectRows
        }
        override suspend fun task(id: String): Task {
            details++; detailError?.let { throw it }; return rows.first { it.id == id }
        }
        override suspend fun saveTask(id: String?, request: TaskRequest): Task {
            writes++; last = request; lastId = id; gate?.await(); writeError?.let { throw it }
            val saved = Task(id ?: "33333333-3333-4333-8333-333333333333", request.projectId,
                projectRows.first { it.id == request.projectId }.name, request.name, request.cost, request.date,
                request.sentOn.takeIf { it.isNotEmpty() }, request.description.takeIf { it.isNotEmpty() })
            rows = rows.filterNot { it.id == saved.id } + saved
            return saved
        }
        override suspend fun createProject(request: ProjectRequest): Project {
            writes++; projectRequest = request; gate?.await(); writeError?.let { throw it }
            val saved = Project("44444444-4444-4444-8444-444444444444", request.name, request.description)
            projectRows = projectRows + saved; return saved
        }
    }
    private fun TasksController.current() = state.value
    private fun TasksController.validDraft() { edit(); draft(TaskDraft(project.id, " New work ", "10,25", "2026-11-10")) }

    @Test fun loadsConcurrentlyAndKeepsCompleteSummaryAndSortedProjects() = runTest {
        val source = Source(); val taskGate = CompletableDeferred<List<Task>>(); val projectGate = CompletableDeferred<List<Project>>()
        var tasksStarted = false; var projectsStarted = false
        source.taskFetch = { tasksStarted = true; taskGate.await() }; source.projectFetch = { projectsStarted = true; projectGate.await() }
        val c = TasksController(source, this); c.refresh(); runCurrent()
        assertTrue(tasksStarted && projectsStarted); assertTrue(c.current().refreshing)
        assertFalse(c.current().tasksLoaded)
        taskGate.complete(source.rows); projectGate.complete(listOf(project.copy(name = "Z"), project.copy(id = "a", name = "A")))
        advanceUntilIdle()
        assertTrue(c.current().tasksLoaded && c.current().projectsLoaded)
        assertEquals(listOf("A", "Z"), c.current().projects.map { it.name })
        assertEquals(TaskSummary(1, BigDecimal("12.50"), 1), c.current().tasks.summary())
    }

    @Test fun emptyArraysAreLoadedButFailedFirstFetchIsNotAnEmptySuccess() = runTest {
        val source = Source().apply { rows = emptyList(); projectRows = emptyList(); taskError = IOException() }
        val c = TasksController(source, this); c.refresh(); advanceUntilIdle()
        assertFalse(c.current().tasksLoaded); assertTrue(c.current().projectsLoaded)
        assertEquals(TaskFailure.NETWORK, c.current().taskError!!.kind)
        source.taskError = null; c.refresh(); advanceUntilIdle()
        assertTrue(c.current().tasksLoaded); assertTrue(c.current().tasks.isEmpty()); assertNull(c.current().taskError)
    }

    @Test fun refreshFailureRetainsDataAndLabelsEachFailedDataset() = runTest {
        val source = Source(); val c = TasksController(source, this); c.refresh(); advanceUntilIdle()
        source.taskError = IOException(); source.projectError = http(500)
        c.refresh(); advanceUntilIdle()
        assertEquals(listOf(row), c.current().tasks); assertEquals(listOf(project), c.current().projects)
        assertEquals(TaskFailure.NETWORK, c.current().taskError!!.kind)
        assertEquals(TaskFailure.SERVER, c.current().projectError!!.kind)
        source.taskError = null; source.projectError = null; c.refresh(); advanceUntilIdle()
        assertNull(c.current().taskError); assertNull(c.current().projectError)
    }

    @Test fun obsoleteUncooperativeFetchCannotRestoreOlderData() = runTest {
        val source = Source(); val old = CompletableDeferred<List<Task>>()
        source.taskFetch = { withContext(NonCancellable) { old.await() } }
        val c = TasksController(source, this); c.refresh(); runCurrent()
        source.taskFetch = null; source.rows = emptyList(); c.refresh(); runCurrent()
        old.complete(listOf(row)); advanceUntilIdle()
        assertTrue(c.current().tasksLoaded); assertTrue(c.current().tasks.isEmpty())
    }

    @Test fun invalidFieldsAndMissingProjectsSendNoRequests() = runTest {
        val source = Source(); val c = TasksController(source, this); c.refresh(); advanceUntilIdle()
        c.edit(); c.draft(TaskDraft(name = " ", cost = "NaN", date = "2026-02-29", sentOn = "bad")); c.saveTask()
        assertEquals(setOf("projectId", "name", "cost", "date", "sentOn"), c.current().fields)
        assertEquals(0, source.writes); assertNotNull(c.current().draft)
        source.projectRows = emptyList(); c.refresh(); advanceUntilIdle(); c.validDraft(); c.saveTask()
        assertEquals(0, source.writes); assertTrue("projectId" in c.current().fields)
    }

    @Test fun projectCreateSelectsReturnedProjectWithoutLosingTaskInput() = runTest {
        val source = Source(); val c = TasksController(source, this); c.refresh(); advanceUntilIdle(); c.validDraft()
        val draft = c.current().draft!!; c.openProject(); c.projectInput(" New client ", " Description ")
        c.saveProject(); advanceUntilIdle()
        assertEquals(ProjectRequest("New client", "Description"), source.projectRequest)
        assertEquals(draft.copy(projectId = "44444444-4444-4444-8444-444444444444"), c.current().draft)
        assertFalse(c.current().projectForm); assertEquals(2, c.current().projects.size)
    }

    @Test fun duplicateProjectIsInlineAndDoesNotAddPhantomOrCloseForm() = runTest {
        val source = Source().apply { writeError = http(409, "Project already exists") }
        val c = TasksController(source, this); c.refresh(); advanceUntilIdle(); c.openProject()
        c.projectInput("Client", "Keep this"); c.saveProject(); advanceUntilIdle()
        assertTrue(c.current().projectForm); assertEquals("Keep this", c.current().projectDescription)
        assertEquals(TaskFailure.DUPLICATE, c.current().projectProblem!!.kind)
        assertEquals(listOf(project), c.current().projects); assertFalse(c.current().uncertain)
    }

    @Test fun repeatedSaveIsSingleInFlightAndSentCreateUpdatesHistoryOnly() = runTest {
        val source = Source().apply { gate = CompletableDeferred() }; val c = TasksController(source, this)
        c.refresh(); advanceUntilIdle(); c.validDraft(); c.draft(c.current().draft!!.copy(sentOn = "2026-11-01"))
        c.saveTask(); c.saveTask(); runCurrent(); assertEquals(1, source.writes); assertTrue(c.current().saving)
        c.closeForm(); assertNotNull(c.current().draft)
        source.gate!!.complete(Unit); advanceUntilIdle()
        assertNull(source.lastId); assertNull(c.current().draft)
        assertEquals(2, c.current().tasks.history().size); assertEquals(1, c.current().tasks.summary().pendingCount)
        assertEquals("New work", c.current().tasks.first { it.id != row.id }.name)
    }

    @Test fun editingUpdatesAllFieldsFromConfirmedResponse() = runTest {
        val source = Source(); val c = TasksController(source, this); c.refresh(); advanceUntilIdle(); c.edit(row)
        val updated = TaskDraft(project.id, " Updated ", "-2,50", "2099-12-31", "2000-01-01", " Details ")
        c.draft(updated); c.saveTask(); advanceUntilIdle()
        assertEquals(row.id, source.lastId); assertEquals(updated.request(), source.last)
        assertEquals("Updated", c.current().selected!!.name); assertEquals("Details", c.current().selected!!.description)
        assertEquals(BigDecimal.ZERO, c.current().tasks.summary().pendingTotal)
    }

    @Test fun statusReadsLatestRecordAndPreservesEveryOtherWritableField() = runTest {
        val source = Source(); val c = TasksController(source, this); c.refresh(); advanceUntilIdle(); c.select(row)
        val latest = row.copy(name = "Edited on web", cost = BigDecimal("-40.15"), date = "2027-01-01", description = "New description")
        source.rows = listOf(latest); c.status("2026-11-10"); advanceUntilIdle()
        assertEquals(1, source.details); assertEquals(latest.writable("2026-11-10"), source.last)
        assertEquals(0, c.current().tasks.summary().pendingCount)
        c.status(""); advanceUntilIdle()
        assertEquals(latest.writable(""), source.last); assertFalse(c.current().selected!!.isSent)
        assertEquals(BigDecimal("-40.15"), c.current().tasks.summary().pendingTotal)
    }

    @Test fun legacyUnassignedAndDeletedTaskNeverCauseShortcutRecreation() = runTest {
        val source = Source(); val c = TasksController(source, this); c.refresh(); advanceUntilIdle(); c.select(row)
        source.rows = listOf(row.copy(projectId = "")); c.status("2026-11-10"); advanceUntilIdle()
        assertEquals(0, source.writes); assertEquals(TaskFailure.PROJECT_MISSING, c.current().problem!!.kind)
        source.detailError = http(404); source.rows = emptyList(); c.status(""); advanceUntilIdle()
        assertEquals(0, source.writes); assertNull(c.current().selected)
        assertEquals(TaskFailure.MISSING, c.current().problem!!.kind)
    }

    @Test fun rejectedSaveRetainsInputWithoutReportingSuccess() = runTest {
        val source = Source().apply { writeError = http(400, "Name required") }
        val c = TasksController(source, this); c.refresh(); advanceUntilIdle(); c.validDraft()
        val draft = c.current().draft; c.saveTask(); advanceUntilIdle()
        assertEquals(draft, c.current().draft); assertEquals(setOf("name"), c.current().fields)
        assertFalse(c.current().uncertain); assertEquals(listOf(row), c.current().tasks)
    }

    @Test fun uncertainWriteSurvivesNavigationAndRequiresSuccessfulReviewBeforeRetry() = runTest {
        val source = Source().apply { writeError = IOException() }; val c = TasksController(source, this)
        c.refresh(); advanceUntilIdle(); c.validDraft(); c.saveTask(); advanceUntilIdle()
        assertTrue(c.current().uncertain); assertNotNull(c.current().draft)
        c.closeForm(); c.validDraft(); c.openProject(); c.projectInput("New", ""); c.saveProject()
        c.closeProject(); c.saveTask(); advanceUntilIdle(); assertEquals(1, source.writes)
        source.taskError = IOException(); c.refresh(); advanceUntilIdle(); c.acknowledgeUncertain()
        assertTrue(c.current().uncertain)
        source.taskError = null; c.refresh(); advanceUntilIdle(); c.acknowledgeUncertain()
        assertFalse(c.current().uncertain); source.writeError = null; c.saveTask(); advanceUntilIdle()
        assertEquals(2, source.writes); assertNull(c.current().draft)
    }

    @Test fun timeoutAfterServerSaveReconcilesWithoutAutomaticPostReplay() = runTest {
        val source = Source(); val c = TasksController(source, this); c.refresh(); advanceUntilIdle(); c.validDraft()
        val draft = c.current().draft!!
        // Simulate the server accepting the create but its response being lost.
        source.rows = source.rows + row.copy(id = "33333333-3333-4333-8333-333333333333", name = draft.name.trim())
        source.writeError = IOException(); c.saveTask(); advanceUntilIdle()
        assertTrue(c.current().uncertain); assertEquals(2, c.current().tasks.size)
        c.saveTask(); c.refresh(); advanceUntilIdle(); assertEquals(1, source.writes)
    }

    @Test fun authenticationExpiryClearsRecordsDraftAndSessionWithoutRetryLoop() = runTest {
        val source = Source(); var expirations = 0; val c = TasksController(source, this) { expirations++ }
        c.refresh(); advanceUntilIdle(); c.validDraft(); source.writeError = http(401)
        c.saveTask(); advanceUntilIdle()
        assertEquals(1, expirations); assertTrue(c.current().authenticationRequired)
        assertTrue(c.current().tasks.isEmpty()); assertTrue(c.current().projects.isEmpty()); assertNull(c.current().draft)
        val reads = source.reads; c.refresh(); c.saveProject(); advanceUntilIdle(); assertEquals(reads, source.reads)
    }

    @Test fun eitherListReturning401ExpiresSessionAndForbiddenDoesNotLoop() = runTest {
        val source = Source().apply { projectError = http(401) }; var expirations = 0
        val c = TasksController(source, this) { expirations++ }; c.refresh(); advanceUntilIdle()
        assertTrue(c.current().authenticationRequired); assertEquals(1, expirations)
        val forbidden = Source().apply { taskError = http(403) }; val other = TasksController(forbidden, this)
        other.refresh(); advanceUntilIdle(); assertEquals(TaskFailure.FORBIDDEN, other.current().taskError!!.kind)
        assertFalse(other.current().authenticationRequired); assertEquals(1, forbidden.reads)
    }
}

